      "title": "ブルガリア縮小と英墺への統治権",
      "body": [
        "だって、イギリスが怒ったら戦争になる。そこで、ロシアが取ったはずの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土を縮小</strong>して、しかも<strong class=\"source-bold\">オスマン帝国<ruby>宗主<rt>そうしゅ</rt></ruby>下に戻した</strong>。さらにイギリスには<strong class=\"source-bold\">キプロス島</strong>、<strong class=\"source-bold\">オーストリア</strong>には<strong class=\"source-bold\">ボスニア・ヘルツェゴヴィナ</strong>の<ruby>統治<rt>とうち</rt></ruby>権というお<ruby>土産<rt>みやげ</rt></ruby>まで持たせた。"
      ],
