      "title": "バルカン問題と三帝同盟の崩壊",
      "body": [
        "ヨーロッパ外交をリードしたビスマルクにも、どうにもならなかったのが<strong class=\"source-bold\">バルカン問題</strong>だよ。バルカン半島のスラヴ人によるトルコへの反乱や、スラヴ人同士の紛争に<strong class=\"source-bold\">オーストリアとロシアが<ruby>介入<rt>かいにゅう</rt></ruby></strong>して対立が深まり、1887年<strong class=\"source-bold\">三帝同盟が崩壊</strong>してしまった。"
      ],
