      "title": "フランスとロシアの接近への警戒",
      "body": [
        "しかも同じころ、<strong class=\"source-bold\">フランス</strong>では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>が起きて、<strong class=\"source-bold\">反ドイツの世論</strong>が盛り上がっている。<ruby>独墺<rt>どくおう</rt></ruby>同盟はかなり強かったから、<strong class=\"source-bold\">ロシアとフランスが反ドイツ・反オーストリアで同盟を結ぶ</strong>かもしれない……。ビスマルクはズルい手を使うしかなくなくなったんだ。"
      ],
