      "id": "modern-c03-l13-p01-048",
      "title": "バルカン進出と再保障条約の更新拒否",
      "body": [
        "この時点ですでに、<strong class=\"source-bold\">ドイツはヨーロッパ有数の工業国に発展</strong>していたから、ヴィルヘルム2世は積極的な対外進出に転換し、オーストリアとともに<strong class=\"source-bold\">バルカン半島への進出</strong>を目指したから、<strong class=\"source-bold\">ロシアとの対立</strong>は避けられない。こうして、<strong class=\"source-bold\">ロシア</strong>との<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約の更新を拒否</strong></span>したんだ。ロシアは捨てられた愛人だな……。"
      ],
      "plainBody": [
        "この時点ですでに、ドイツはヨーロッパ有数の工業国に発展していたから、ヴィルヘルム2世は積極的な対外進出に転換し、オーストリアとともにバルカン半島への進出を目指したから、ロシアとの対立は避けられない。こうして、ロシアとの再保障条約の更新を拒否したんだ。ロシアは捨てられた愛人だな……。"
      ],
