      "title": "ロシア軍の満洲占領とイギリスの財政難",
      "body": [
        "かわりに日本に最大兵力を出させたけど、<ruby>鎮圧<rt>ちんあつ</rt></ruby>後も<strong class=\"source-bold\">ロシア軍は<ruby>撤退<rt>てったい</rt></ruby>せず</strong>に<strong class=\"source-bold\">満洲<ruby>占領<rt>せんりょう</rt></ruby></strong>を続けていた。ホントならイギリスは、<strong class=\"source-bold\">中国に軍隊を送ってロシアを抑え込みたい</strong>ところだったんだけど、<strong class=\"source-bold\">南ア戦争で財政難</strong>になってる……。"
      ],
