        "かわりに日本に最大兵力を出させたけど、鎮圧後もロシア軍は撤退せずに満洲占領を続けていた。ホントならイギリスは、中国に軍隊を送ってロシアを抑え込みたいところだったんだけど、南ア戦争で財政難になってる……。"
