      "title": "「光栄ある孤立」を放棄して日英同盟へ",
      "body": [
        "ついに<strong class=\"source-bold\">イギリス</strong>が「<strong class=\"source-bold\">光栄ある孤立</strong>」を<ruby>放棄<rt>ほうき</rt></ruby>して、<strong class=\"source-bold\">ロシアに対抗</strong>するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日英同盟</strong></span>を結んだんだ。こうして極東の日本を加えて、「<strong class=\"source-bold\"><ruby>独墺<rt>どくおう</rt></ruby>の“2”</strong>」と「<strong class=\"source-bold\">露仏の“2”</strong>」、そして「<strong class=\"source-bold\">日英の“2”……うーん、まだ1.5くらい</strong>」という状態だね。"
      ],
