      "id": "modern-c03-l13-p01-081",
      "title": "第1次モロッコ事件とドイツの脅威",
      "body": [
        "ちょっとだけ時代をさかのぼるよ。日露戦争中に、<strong class=\"source-bold\">ドイツ</strong>は英仏の関係を悪化させるために衝撃的な事件を起こした。だって<strong class=\"source-bold\">英仏協商にムカついた</strong>んだもん。「フランスにモロッコを取らせたくない！」と思った<strong class=\"source-bold\">ドイツ皇帝</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次モロッコ事件</strong></span>を起こすと、英仏両国は「<strong class=\"source-bold\">ドイツの脅威が現実になった</strong>！」って焦ったんだ。"
      ],
      "plainBody": [
        "ちょっとだけ時代をさかのぼるよ。日露戦争中に、ドイツは英仏の関係を悪化させるために衝撃的な事件を起こした。だって英仏協商にムカついたんだもん。「フランスにモロッコを取らせたくない！」と思ったドイツ皇帝ヴィルヘルム2世が第1次モロッコ事件を起こすと、英仏両国は「ドイツの脅威が現実になった！」って焦ったんだ。"
      ],
