      "title": "イタリア＝トルコ戦争とリビア",
      "body": [
        "さらに、<strong class=\"source-bold\">第2次モロッコ事件</strong>で「英仏 vs. 独の戦争が起きるかもしれない！」という<strong class=\"source-bold\">国際的な緊張</strong>が高まると、ドサクサに紛れて<strong class=\"source-bold\">イタリア</strong>がオスマン帝国（トルコ）と開戦！ この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア＝トルコ戦争</strong></span>に勝利したイタリアは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリポリ・キレナイカ</strong></span>を植民地にして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リビア</strong></span>と改称した。"
      ],
      "plainBody": [
        "さらに、第2次モロッコ事件で「英仏 vs. 独の戦争が起きるかもしれない！」という国際的な緊張が高まると、ドサクサに紛れてイタリアがオスマン帝国（トルコ）と開戦！ このイタリア＝トルコ戦争に勝利したイタリアは、トリポリ・キレナイカを植民地にして、リビアと改称した。"
      ],
