      "body": [
        "そしたら、ロシア軍も予想外に早くドイツに<ruby>侵入<rt>しんにゅう</rt></ruby>していて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東部戦線</strong></span>ではいきなり<strong class=\"source-bold\">独露両軍が<ruby>衝突<rt>しょうとつ</rt></ruby></strong>したんだ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンネンベルクの戦い</strong></span>は、準備が遅れていたにもかかわらず、<strong class=\"source-bold\">ヒンデンブルク</strong>率いる<strong class=\"source-bold\">ドイツ軍がロシア軍を破った</strong>。"
      ],
