        "さらに1915年になると、<strong class=\"source-bold\">中立を宣言していた</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア</strong></span>が<strong class=\"source-bold\">連合国（三国協商側）で参戦</strong>した。これね、「連合国側で参戦したら<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>未回収<rt>みかいしゅう</rt></ruby>のイタリア</strong></span>を返してあげるよ」っていうイギリスの誘いにイタリアが乗ったんだよ（<strong class=\"source-bold\">ロンドン秘密条約</strong>）。"
