      "title": "各国の戦時体制とヴェルダン攻撃",
      "body": [
        "戦線がほとんど動かないまま1916年に突入すると、各国では強力な戦時体制（英は<strong class=\"source-bold\">ロイド＝ジョージ</strong>、仏は<strong class=\"source-bold\">クレマンソー</strong>の挙国一致内閣、独は<strong class=\"source-bold\">軍部独裁体制</strong>）がつくられ、状況をなんとか打ち破ろうと、<strong class=\"source-bold\">西部戦線</strong>では<strong class=\"source-bold\">ドイツ軍</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルダン<ruby>要塞<rt>ようさい</rt></ruby></strong></span>に猛攻撃をかけたんだ。"
      ],
