      "id": "modern-c03-l13-p03-020",
      "title": "ルシタニア号事件とアメリカ参戦",
      "body": [
        "1915年に起きた<strong class=\"source-bold\">ルシタニア号事件</strong>（イギリス船がドイツの潜水艦に<ruby>撃沈<rt>げきちん</rt></ruby>されて、アメリカ人128名が死亡した事件）をきっかけに<strong class=\"source-bold\">ドイツに対する強硬論</strong>が巻き起こっていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>は、1917年に<strong class=\"source-bold\">ドイツ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">無制限潜水艦作戦</strong></span>を開始すると、<strong class=\"source-bold\">これを口実に参戦した</strong>んだ。"
      ],
      "plainBody": [
        "1915年に起きたルシタニア号事件（イギリス船がドイツの潜水艦に撃沈されて、アメリカ人128名が死亡した事件）をきっかけにドイツに対する強硬論が巻き起こっていたアメリカは、1917年にドイツが無制限潜水艦作戦を開始すると、これを口実に参戦したんだ。"
      ],
