      "id": "modern-c03-l13-p03-021",
      "title": "石井・ランシング協定と日米の調整",
      "body": [
        "ちなみに、1917年に<strong class=\"source-bold\">石井・ランシング協定</strong>を結んで、<strong class=\"source-bold\">日本の中国における特殊権益</strong>と、<strong class=\"source-bold\">アメリカの中国への機会均等</strong>を相互承認したのは、アメリカがヨーロッパに<ruby>介入<rt>かいにゅう</rt></ruby>する前に<strong class=\"source-bold\">日米関係を調整しておきたいと思った</strong>からだよ。"
      ],
