      "id": "modern-c03-l13-p03-023",
      "title": "ロシア脱落で西部戦線に集中するドイツ",
      "body": [
        "ただ、連合国側でも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア革命</strong></span>後の1918年に結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレスト＝リトフスク条約</strong></span>でドイツとロシアの講和が実現し、<strong class=\"source-bold\">ロシアが戦争から脱落</strong>したため<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.256</span>、ドイツは西部戦線に集中できるようになった。"
      ],
