      "id": "modern-c03-l13-p03-030",
      "title": "感染の拡大と同盟国側の脱落",
      "body": [
        "各国は軍内部での感染を隠していたけど、<strong class=\"source-bold\">インフルエンザの大流行でもはや軍は身動きが取れなくなった</strong>んだ。同盟国側は弱い国から脱落していき、9月に<strong class=\"source-bold\">ブルガリア</strong>、10月に<strong class=\"source-bold\">オスマン帝国</strong>、さらに<strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong>が降伏すると、戦っているのは<strong class=\"source-bold\">ドイツだけ</strong>になったんだ。"
      ],
      "plainBody": [
        "各国は軍内部での感染を隠していたけど、インフルエンザの大流行でもはや軍は身動きが取れなくなったんだ。同盟国側は弱い国から脱落していき、9月にブルガリア、10月にオスマン帝国、さらにオーストリア＝ハンガリー帝国が降伏すると、戦っているのはドイツだけになったんだ。"
      ],
