      "body": [
        "これに対して<strong class=\"source-bold\">ソヴィエト</strong>には、<strong class=\"source-bold\">エスエル</strong>（左派）や<strong class=\"source-bold\">メンシェヴィキ</strong>の指導のもとで、労働者や兵士、<strong class=\"source-bold\">農民</strong>が集まった。彼らは「戦争やめて食糧よこせ〜（パンと平和）」と、<strong class=\"source-bold\">停戦を求めていた</strong>んだ。"
      ],
