      "body": [
        "臨時政府が倒された翌日には、<strong class=\"source-bold\">全ロシア＝ソヴィエト会議</strong>（第2回）が開かれた。会議ではまず、当面の政府として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民委員会議</strong></span>が設置され、<strong class=\"source-bold\">議長にレーニン、外務人民委員にトロツキー、民族人民委員にスターリン</strong>が選ばれた。"
      ],
      "plainBody": [
        "臨時政府が倒された翌日には、全ロシア＝ソヴィエト会議（第2回）が開かれた。会議ではまず、当面の政府として人民委員会議が設置され、議長にレーニン、外務人民委員にトロツキー、民族人民委員にスターリンが選ばれた。"
      ],
