        "全ロシア＝ソヴィエト会議では、ロシア初の普通選挙（女性にも参政権があるよ！）による憲法制定会議の招集を決めて、それまでの暫定的な政府として人民委員会議をつくった。ってことは、選挙で勝たないと正式な政府にはなれないんだよ。"
