      "id": "modern-c03-l13-p04-030",
      "title": "農民の支持と停戦を急ぐ理由",
      "body": [
        "<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ</strong></span>はかなり焦っていた。だって、<strong class=\"source-bold\">一番人口が多い農民</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span>／社会主義者・革命家党】</strong>を支持しているからね。選挙で勝つには、すぐにでも<strong class=\"source-bold\">農民たちが求めている停戦を実現しないとマズい</strong>。だからトロツキーは、ドイツとの<ruby>講和<rt>こうわ</rt></ruby>を急いだんだ。"
      ],
      "plainBody": [
        "ボリシェヴィキはかなり焦っていた。だって、一番人口が多い農民はエスエル【社会革命党／社会主義者・革命家党】を支持しているからね。選挙で勝つには、すぐにでも農民たちが求めている停戦を実現しないとマズい。だからトロツキーは、ドイツとの講和を急いだんだ。"
      ],
