      "title": "吉野作造の民本主義",
      "body": [
        "これって、日本で初めて<strong class=\"source-bold\">大衆運動によって内閣が倒れた</strong>ってことだね。こうした状況を受けて、1916年には政治学者の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>吉野作造<rt>よしのさくぞう</rt></ruby></strong></span>が、天皇主権のもとでもデモクラシーが可能であるとして、民衆のための政治をおこなう「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民本主義</strong></span>」を唱えたんだ。"
      ],
      "plainBody": [
        "これって、日本で初めて大衆運動によって内閣が倒れたってことだね。こうした状況を受けて、1916年には政治学者の吉野作造が、天皇主権のもとでもデモクラシーが可能であるとして、民衆のための政治をおこなう「民本主義」を唱えたんだ。"
      ],
