export const sourcePages = {
  "236": "<h2>236</h2>\n<h3><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第一次世界大戦とロシア革命</strong></span></h3>\n<p>さあ、今回はいよいよ<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">19世紀以降のヨーロッパの国際関係を第一次世界大戦まで</strong></u>一気に見ていくよ。これまで見てきた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby>の対立</strong></u>がからみあって、ヨーロッパ全体を巻き込む戦争にまで発展してしまうんだ。</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">第一次世界大戦にいたる国際関係</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">237〜245ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">「ヨーロッパの火薬庫」</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">246〜249ページ</span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">第一次世界大戦</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">249〜253ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">ロシア革命</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">253〜257ページ</span></td></tr></tbody></table></div>\n<blockquote><p>今回はビスマルク外交から第一次世界大戦まで一気に見ていくよ！</p></blockquote>\n<p>政治学や歴史学で「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">長い19世紀</strong></u>」って言い方があるんだけど、これは<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">19世紀の国際関係</strong></u>が「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">1914年の第一次世界大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong></u>」で大きな区切りを迎えたからできた呼び方だよ。各国が<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">帝国主義</strong></u>を進めるとさまざまな対立が起きて、その結果、これまでになかったような大きな戦争を引き起こした。今回は、対立の発生から第一次世界大戦の勃発までの国際関係の変化をまとめて見ていくよ。大学の授業にある「<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">国際関係論</strong></u>」でも題材になるような範囲だから、ちょっと難しいかもしれないけど、<ruby>頑張<rt>がんば</rt></ruby>っていこう！ さらに、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">第一次世界大戦</strong></u>と大戦中に起きた<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">ロシア革命</strong></u>まで一気に進めるからね！</p>\n<p>それじゃあ、第一次世界大戦とロシア革命の始まり〜。</p>",
  "237": "<h2>237</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦にいたる国際関係</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">第一次世界大戦にいたる国際関係</strong></span></h3>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">ビスマルク外交の時代［1871〜1890］</em></strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td>ドイツに好意的</td><td><strong class=\"source-bold\">英</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">←</span></span></td></tr><tr><td>「光栄ある孤立」</td><td><span data-source-marker=\"dashed-arrow\">······</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><strong class=\"source-bold\">仏</strong></td><td><strong class=\"source-bold\">独</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">再保障条約</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">［1887］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"dashed-arrow\">······</span></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">三帝同盟</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">［1873/1881］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"fill\">—</span></span></td></tr><tr><td><strong class=\"source-bold\">露</strong></td><td><strong class=\"source-bold\">墺</strong></td><td><strong class=\"source-bold\">日</strong></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">三国同盟</strong></span></td><td>［1882］</td><td><span data-source-marker=\"fill\">—</span></td></tr><tr><td><strong class=\"source-bold\">伊</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td><td></td></tr></tbody></table></div>\n<blockquote><p>ビスマルクの目標は「フランスの孤立！」一番大事なのはロシアとの関係だ！</p></blockquote>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">ビスマルク外交</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三帝同盟</strong></span></span> ［1873］</td><td>…… <strong class=\"source-bold\">ドイツ・オーストリア・ロシア</strong>で<ruby>締結<rt>ていけつ</rt></ruby></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><ruby>独墺<rt>どくおう</rt></ruby>同盟 ［1879］</td><td>……ドイツとオーストリアの軍事同盟</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span>新三帝同盟 ［1881］</td><td>……三帝同盟の復活　<span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>1887年崩壊</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国同盟</strong></span></span> ［1882］</td><td>…… <strong class=\"source-bold\">ドイツ・オーストリア・イタリア</strong>で締結</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約</strong></span></span> <strong class=\"source-bold\">【二重保障条約】</strong> ［1887］</td><td>…… <strong class=\"source-bold\">ドイツ・ロシア</strong>間の秘密条約</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">「ビスマルク外交」って何？ ポイントは「フランスの孤立化」だ！</strong></span></h4>\n<p>1871年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ帝国</strong></span>を成立させた<ruby>宰相<rt>さいしょう</rt></ruby><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>は、できたばかりのドイツの安全をどうやって守るかを考えた。これまではひたすら<strong class=\"source-bold\">軍備拡大</strong>（「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">鉄血政策</strong></span>」だ！）によって統一を進めたけど、これからは<strong class=\"source-bold\">国内の産業発展にもお金を使いたい</strong>。軍事費を抑えるためにも、しばらく<strong class=\"source-bold\">戦争は起きてほしくなかった</strong>んだ。</p>\n<p>しかし、それを脅かすのが<strong class=\"source-bold\">フランス</strong>だ。さすがに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普仏<rt>ふふつ</rt></ruby>戦争</strong></span>ではちょっとやりすぎた。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルザス・ロレーヌ</strong></span>を奪い、ヴェルサイユ宮殿に乗り込んでドイツ皇帝の<ruby>戴冠式<rt>たいかんしき</rt></ruby>をやってフランス人のプライドをズタズタにして、<ruby>賠償金<rt>ばいしょうきん</rt></ruby>まで払わせたもんね。<strong class=\"source-bold\">フランス人のドイツへの<ruby>復讐<rt>ふくしゅう</rt></ruby>心</strong>はハンパないんだよ。もしどこかで戦争が起きたら、それを利用してフランスがドイツに攻め込んでくる可能性は高かった。</p>\n<p>そして<strong class=\"source-bold\">イギリス</strong>も、オーストリア、フランスという2大国を力でねじ伏せて統一</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "238": "<h2>238</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>した<strong class=\"source-bold\">ドイツを警戒している</strong>。「ヨーロッパの真ん中に、とんでもない大国ができた」と思われたら、ドイツ包囲網をつくられるかもしれない。</p>\n<p>そして各国は、「いかに自分が不利にならないか」ってことを考えている。<strong class=\"source-bold\">ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>は5大国（英・仏・露・独・墺）</strong>だから、2つに分かれるとしたら3対2になるよね。だから各国は、<strong class=\"source-bold\">絶対に“2”のほうにはなりたくない</strong>んだ。これ、ずっと出てくるから覚えといてね。ビスマルクは、「何があっても<strong class=\"source-bold\">ドイツが3、あわよくば4のほうにいる</strong>」状態にしておきたい。</p>\n<p>それじゃ、これらを解決するにはどうすればいいんだろ？ まずは<strong class=\"source-bold\">フランスを孤立</strong>させて、戦争を起こした瞬間に周りが全部敵になるように、<strong class=\"source-bold\">フランスを包囲する同盟をヨーロッパ中に張りめぐらせればいい</strong>。そして、一番大事なのはロシアとの関係だね。ロシアがフランスと同盟したらドイツは挟み撃ちになるから、ビスマルクは<strong class=\"source-bold\">ロシアとの同盟関係を重視した</strong>んだ。さらに<strong class=\"source-bold\">国際関係をリードして勢力均衡を図り</strong>、ヨーロッパで戦争が起きないようにする。だから、ドイツは対外進出をしないよ。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク外交</strong></span>」だ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">まずはロシアとの同盟形成！ でも……できたのは「三帝同盟」だ</strong></span></h4>\n<p>そこで<strong class=\"source-bold\">ビスマルクはロシアに接近</strong>して、ロシアがフランスをキライになるように、想い出を語った。「ロシアは<strong class=\"source-bold\">クリミア戦争</strong>の時、イギリスと“フランス”にひどい目に遭わされましたな」って。さらに「<strong class=\"source-bold\">フランスみたいな革命の国</strong>と付き合ったら、何されるかわかりませんよ。ロシアの味方には、“ドイツ”がふさわしい」って付け加えた。</p>\n<p>ロシアは「確かにそうだな」って思った。こうして、<strong class=\"source-bold\">ロシアがドイツと同盟を結ぶ</strong>気になったところで、「あっ、1つ忘れてました。この同盟“<strong class=\"source-bold\">オーストリアも入れる</strong>”けど、もちろんいいですね」って、しれっと言ったんだ。</p>\n<p>だって、<strong class=\"source-bold\">オーストリアとロシア</strong>はどちらも<strong class=\"source-bold\">バルカン半島への進出を狙っている</strong>から、そもそも仲が悪い！ <strong class=\"source-bold\">下手したら戦争になる</strong>かもしれないよね。そして、<strong class=\"source-bold\">オーストリア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>普墺<rt>ふおう</rt></ruby>戦争</strong></span>の時にベーメンを返してもらった想い出があるから、ドイツが好き♡。<strong class=\"source-bold\">ドイツとオーストリアが仲が良い</strong>ってことは、ロシアとオーストリアが戦争になったら、<strong class=\"source-bold\">ロシアがフランスと組むかもしれない</strong>。なんとしてもロシアとオーストリアの戦争を避けたいから、<strong class=\"source-bold\">両国を入れた3国の同盟</strong>にしたかったんだよ。対立する2国を一緒の同盟に入れるのは、ビスマルクお得意の「<strong class=\"source-bold\">戦争封じ</strong>」だ。</p>\n<p>ロシアは一瞬悩んだけど、「ドイツが敵じゃないほうがいいし、ロシアが“3”のほうにいられる」と思った。だって、この3国で<strong class=\"source-bold\">ドイツが一番強い</strong>んだもん。こう</p>\n<blockquote><p>対立する2国を含めた3国の同盟をつくる。ビスマルクお得意の「戦争<ruby>封<rt>ふう</rt></ruby>じ」だ！</p></blockquote>",
  "239": "<h2>239</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦にいたる国際関係</u></p>\n<p>して1873年、<strong class=\"source-bold\">ドイツ、オーストリア、ロシア</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三帝同盟</strong></span>が成立したよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアの南下に各国が反発。ベルリン会議で戦争の危機を回避！</strong></span></h4>\n<p>しかし、安定は長くは続かなかった。<strong class=\"source-bold\">ロシア</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露土<rt>ろと</rt></ruby>戦争</strong></span>を起こし、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サン＝ステファノ条約</strong></span>で<strong class=\"source-bold\">バルカン半島への南下を成功させた</strong>よね。この戦争は、そもそもクリミア戦争のパリ条約に違反して起こした戦争だから、<strong class=\"source-bold\">イギリス、オーストリアが猛反発</strong>！ もしイギリス・オーストリアとロシアが開戦すれば……おそらくフランスが動く。ビスマルクは焦った……「<strong class=\"source-bold\">こりゃ第2次クリミア戦争だ……</strong>」。</p>\n<p>こうなったら、ドイツは動きようがないんだよ。<strong class=\"source-bold\">ロシアにつけば、英仏が敵</strong>になり、<strong class=\"source-bold\">オーストリアまでも敵</strong>になる。かといって<strong class=\"source-bold\">ロシアを敵にしたら、戦後にロシアとフランスが接近</strong>するかもしれない……結果は「<strong class=\"source-bold\">3対2の“2”になる</strong>」か「<strong class=\"source-bold\">フランスがロシアと組む</strong>」か、どう転んでも悪夢だ。「なんとしても、戦争だけは回避しなければマズい！」</p>\n<p>そこで<strong class=\"source-bold\">ビスマルク</strong>は「<strong class=\"source-bold\">誠実な仲介人</strong>」と称して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会議</strong></span>を開いた。会議のなかでビスマルクは、<strong class=\"source-bold\">ほぼ全面的にイギリスとオーストリアの味方</strong>をした（条約の中身は<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.106〜107</span>参照）。だって、イギリスが怒ったら戦争になる。そこで、ロシアが取ったはずの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>の<strong class=\"source-bold\">領土を縮小</strong>して、しかも<strong class=\"source-bold\">オスマン帝国<ruby>宗主<rt>そうしゅ</rt></ruby>下に戻した</strong>。さらにイギリスには<strong class=\"source-bold\">キプロス島</strong>、<strong class=\"source-bold\">オーストリア</strong>には<strong class=\"source-bold\">ボスニア・ヘルツェゴヴィナ</strong>の<ruby>統治<rt>とうち</rt></ruby>権というお<ruby>土産<rt>みやげ</rt></ruby>まで持たせた。ついでに<strong class=\"source-bold\">英仏独の密約</strong>で<strong class=\"source-bold\">フランスのチュニジア<ruby>占領<rt>せんりょう</rt></ruby>を黙認</strong>した。これ、ビスマルクの仕掛けた時限爆弾。あとで爆発するからね。</p>\n<p>さすがにロシアは「三帝同盟を結んだくせに、お前は味方じゃないのかよ！」って怒った。かわりにイギリスがビスマルクのファンになった。会議に出席した首相<strong class=\"source-bold\">ディズレーリ</strong>は「ビスマルクはなかなかいいヤツじゃないか」って思ったんだね。会議の結果は「<strong class=\"source-bold\">独露関係が悪化した（事実上の三帝同盟崩壊）</strong>」ことと「<strong class=\"source-bold\">英独関係が良好になった</strong>」ことがポイントだよ。</p>\n<blockquote><p>ベルリン会議で怒らせちゃったロシアとの関係は復活できるのかな？</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ロシアとの関係を改善しつつ、イタリアを同盟に取り込め！</strong></span></h4>\n<p>ベルリン会議のあと、<strong class=\"source-bold\">ビスマルク</strong>は<strong class=\"source-bold\">オーストリアとの同盟関係を中心</strong>に同盟をつくり直したよ。まずは<ruby>独墺<rt>どくおう</rt></ruby>同盟を結び、オーストリアに対しては「ロシアがバルカンに進出してきたら、<strong class=\"source-bold\">ドイツは全面的にオーストリアの味方です</strong>よ」って言って安心させた。でも本当は、<strong class=\"source-bold\">ロシアともう一度同盟を結ぶための策略</strong>なんだよ。</p>\n<p>ビスマルクの思ったとおり、ロシアは焦った……。だって、バルカン半島に進出したら、周りは敵ばかりでしょ。ビスマルクはロシアに言った。「英仏がずっと敵のロシアが、<strong class=\"source-bold\">独墺まで敵に回したら</strong>どうなりますか？ あなたは3対2の“2”</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "240": "<h2>240</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p><strong class=\"source-bold\">あるいは“1”のほう</strong>になりますよ」ってね。<strong class=\"source-bold\">孤立したロシア</strong>は再びドイツの陣営に戻り、<strong class=\"source-bold\">三帝同盟が復活</strong>したよ（新三帝同盟）。</p>\n<p>さらに、ビスマルクが仕掛けた時限爆弾が爆発した！ <strong class=\"source-bold\">フランスがチュニジアを保護国化</strong>すると、<strong class=\"source-bold\">イタリアが怒った</strong>んだ。だって、チュニジアってもともとカルタゴだ。イタリアの夢はローマ帝国の復活！ イタリア半島統一の次はポエニ戦争だ。でもフランスに取られた……。「も〜、<strong class=\"source-bold\">カルタゴほしかったのに</strong>〜」</p>\n<p>そこに現れたのが<strong class=\"source-bold\">ビスマルク</strong>だ！ 「フランスってイヤなヤツだろ。君がほしかったカルタゴを取っちゃって」って<strong class=\"source-bold\">イタリアに接近</strong>した。そもそもイタリアはビスマルクがキライじゃない。だって、<strong class=\"source-bold\">ヴェネツィアを<ruby>併合<rt>へいごう</rt></ruby>できたのはビスマルクのおかげ</strong>だ（<ruby>普墺<rt>ふおう</rt></ruby>戦争の時だ）。</p>\n<p>こうして、<strong class=\"source-bold\">イタリアが同盟を結ぶ気まんまん</strong>になったところで、お得意の戦争<ruby>封<rt>ふう</rt></ruby>じ。「同盟結ぶなら、<strong class=\"source-bold\">オーストリアも一緒</strong>だからよろしく」ってさ。イタリアは一瞬迷った……。だって、<strong class=\"source-bold\">オーストリアとイタリア</strong>の間には「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>未回収<rt>みかいしゅう</rt></ruby>のイタリア</strong></span>」問題がある。ただ、<strong class=\"source-bold\">イタリアはチュニジアをフランスに取られたショックが大きかった</strong>から、同盟を結ぶことにしたんだ。こうして、<strong class=\"source-bold\">ドイツ・オーストリア・イタリア</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国同盟</strong></span>ができたよ。</p>\n<blockquote><p>フランスのチュニジア<ruby>占領<rt>せんりょう</rt></ruby>を黙認したのは、イタリアを取り込むための策略だ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ビスマルク外交がほころび始めたけど、なんとかロシアを<ruby>繋<rt>つな</rt></ruby>ぎ止めた！</strong></span></h4>\n<p>ヨーロッパ外交をリードしたビスマルクにも、どうにもならなかったのが<strong class=\"source-bold\">バルカン問題</strong>だよ。バルカン半島のスラヴ人によるトルコへの反乱や、スラヴ人同士の紛争に<strong class=\"source-bold\">オーストリアとロシアが<ruby>介入<rt>かいにゅう</rt></ruby></strong>して対立が深まり、1887年<strong class=\"source-bold\">三帝同盟が崩壊</strong>してしまった。しかも同じころ、<strong class=\"source-bold\">フランス</strong>では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブーランジェ事件</strong></span>が起きて、<strong class=\"source-bold\">反ドイツの世論</strong>が盛り上がっている。<ruby>独墺<rt>どくおう</rt></ruby>同盟はかなり強かったから、<strong class=\"source-bold\">ロシアとフランスが反ドイツ・反オーストリアで同盟を結ぶ</strong>かもしれない……。ビスマルクはズルい手を使うしかなくなくなったんだ。</p>\n<p>1887年、ビスマルクは<strong class=\"source-bold\">ロシア</strong>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約</strong></span>を結んだ。これは「両国のいずれかが攻撃を受けた時、<strong class=\"source-bold\">お互いに中立を守る</strong>」って条約なんだけど、具体的には「<strong class=\"source-bold\">ロシアとオーストリアが戦争になったら、ドイツは中立</strong>」で「<strong class=\"source-bold\">ドイツとフランスが戦争になったら、ロシアは中立</strong>」ってことだよ。よく考えてね。<strong class=\"source-bold\">独墺同盟</strong>では「ロシアとオーストリアが戦争になったら、<strong class=\"source-bold\">ドイツはオーストリアの味方</strong>」って言ってるから、これって人間関係、というか恋愛に例えたら、完全に浮気だ。オーストリアが本命で、ロシアが愛人。両方に「愛してるのは君だけだよ」と言ってる！。ここまでしてでも、<strong class=\"source-bold\">ロシアとフランスの接近を恐れていた</strong>ってことだ。</p>",
  "241": "<h2>241</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦にいたる国際関係</u></p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">ドイツ外交の転換 ［1890〜1904］</em></strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">日英同盟</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\">［1902］</span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><span data-source-marker=\"fill\">—</span></span></td></tr><tr><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">英</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露</strong></span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><strong class=\"source-bold\">独</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td>ファショダ事件後に接近</td><td><span data-source-marker=\"dashed-arrow\">······</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">仏</strong></span></td><td><strong class=\"source-bold\">墺</strong></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">日</strong></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">三国同盟</strong></span></td><td><span data-source-marker=\"fill\">—</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><strong class=\"source-bold\">伊</strong></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">露仏同盟</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\">［1891］</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr></tbody></table></div>\n<blockquote><p>列強が3つのグループになるのがポイントだよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヴィルヘルム2世の親政が始まると……ビスマルクが恐れていた<ruby>露仏<rt>ろふつ</rt></ruby>同盟が成立！</strong></span></h4>\n<p>1890年、<strong class=\"source-bold\">ビスマルクが退陣</strong>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世の親政</strong></span>が始まったよね。この時点ですでに、<strong class=\"source-bold\">ドイツはヨーロッパ有数の工業国に発展</strong>していたから、ヴィルヘルム2世は積極的な対外進出に転換し、オーストリアとともに<strong class=\"source-bold\">バルカン半島への進出</strong>を目指したから、<strong class=\"source-bold\">ロシアとの対立</strong>は避けられない。こうして、<strong class=\"source-bold\">ロシア</strong>との<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">再保障条約の更新を拒否</strong></span>したんだ。ロシアは捨てられた愛人だな……。</p>\n<p>外交と恋愛は似てるよ！。ほら！ 失恋した直後に優しくされると、付き合う可能性が高いでしょ。<strong class=\"source-bold\">ロシアに優しくしたのはフランス</strong>だよ。<strong class=\"source-bold\">フランスもドイツに孤立させられていた</strong>から、「君もドイツにひどい目に遭わされたのか……僕と一緒だね！ ジュテーム」みたいな感じで愛が芽生えた♡。こうして<strong class=\"source-bold\">反ドイツ</strong>で結ばれたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露仏同盟</strong></span>だ。以後ロシアは、<strong class=\"source-bold\">フランスからの投資</strong>によって工業化を進め、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア鉄道</strong></span>の建設も始まったんだ。これが、ロシアが積極的な東アジア進出を始めた背景だよ。</p>\n<p>この時点での5大国は「<strong class=\"source-bold\">独墺の“2”</strong>」と「<strong class=\"source-bold\">露仏の“2”</strong>」、そして「<strong class=\"source-bold\">イギリスの“1”</strong>」という状態だね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">敵がどんどん増えるイギリス。ヨーロッパ中が敵だらけになった！</strong></span></h4>\n<p>19世紀後半の<strong class=\"source-bold\">イギリス</strong>は、圧倒的な<strong class=\"source-bold\">海軍力と経済力</strong>を背景に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">光栄ある孤立</strong></span>」政策をとっていたよね。同盟なんて結ばなくても、世界中に軍隊を送って<ruby>覇権<rt>はけん</rt></ruby>を握れたんだもん。例えば、<strong class=\"source-bold\">イギリスはずっとロシアの南下政策を警戒</strong>していたから、ロシアが勢力を拡大しそうになった時には、<strong class=\"source-bold\">フランスやオーストリアと手を組んで<ruby>潰<rt>つぶ</rt></ruby>せ</strong>ばよかった。でも、そうもいかなくなる。だって、<strong class=\"source-bold\">アフリカ分割をめぐる対立</strong>が</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "242": "<h2>242</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>激化したんだもん。1884年の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン＝コンゴ会議</strong></span>ののち、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ縦断政策</strong></span>を進める<strong class=\"source-bold\">イギリス</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マフディー運動</strong></span>で苦しめられているころ、<strong class=\"source-bold\">フランス</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ横断政策</strong></span>でスーダンを狙っていたよね。これじゃあ<strong class=\"source-bold\">フランスとは協力できない</strong>。でも、<strong class=\"source-bold\">ビスマルク時代</strong>にはドイツがあんまり対外進出をしなかったから、<strong class=\"source-bold\">英独関係は悪くなかった</strong>。つまり、気持ち的には「ドイツは味方」だったんだよ。</p>\n<p>ところが、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>が「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界政策</strong></span>」を始めると、ドイツも危険な国になった！ <strong class=\"source-bold\">ドイツ</strong>が進める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3B政策</strong></span>は、<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3C政策</strong></span>と<strong class=\"source-bold\">全面的に対立</strong>する。イギリスは、インドを脅かすヤツは絶対許せない！ ついに<strong class=\"source-bold\">ドイツも敵になった</strong>。しかも<strong class=\"source-bold\">ドイツ海軍の大拡張</strong>で、イギリス海軍の優位も揺らぎ始めている。両国の<strong class=\"source-bold\">建艦競争</strong>の始まりだ。</p>\n<p>そんな時期に起きたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファショダ事件</strong></span>だよ。<strong class=\"source-bold\">イギリスのアフリカ縦断政策とフランスのアフリカ横断政策が衝突</strong>し、「英仏戦争が始まるかも！」って危機になったよね。この前後で<strong class=\"source-bold\">英仏両国は、それぞれの外交を考え直した</strong>。</p>\n<p>フランスは「イギリスと開戦しても勝てない」って思ったから、<strong class=\"source-bold\">スーダンはイギリスに譲る</strong>ことにした。これを見たイギリスは、増えてしまった敵の優先順位を考え直したんだ。だって、全部を敵に回すのはさすがにキツいでしょ？ 「<strong class=\"source-bold\">ロシア、フランス、ドイツ……どの国が一番ヤバいか？</strong>」。イギリス外交の原則は「インドを狙うヤツは許さない！」ってことだから、<strong class=\"source-bold\">3B政策でインドを脅かすドイツ、中央アジアに南下してくるロシア</strong>はインドへの脅威になるから絶対に敵だけど……<strong class=\"source-bold\">ファショダ事件で譲歩したフランス</strong>は「そんなに脅威じゃないのでは？」と思った。これが、のちに<strong class=\"source-bold\">英仏が接近する伏線</strong>だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">東アジア進出を強化するロシア。イギリスは「光栄ある孤立」を捨てた！</strong></span></h4>\n<p><strong class=\"source-bold\"><ruby>露仏<rt>ろふつ</rt></ruby>同盟の成立後、ロシア</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シベリア鉄道</strong></span>を建設して東アジアにも積極的に進出してきた。そして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>日清<rt>にっしん</rt></ruby>戦争</strong></span>後には、<strong class=\"source-bold\">フランス・ドイツ</strong>を誘って<strong class=\"source-bold\">日本に<ruby>遼東<rt>りょうとう</rt></ruby>半島返還を要求</strong>したよね。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国<ruby>干渉<rt>かんしょう</rt></ruby></strong></span>が、<strong class=\"source-bold\">日本とロシアの対立</strong>の始まりだ。さらに、中国で起きた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>義和団<rt>ぎわだん</rt></ruby>戦争</strong></span>では、日本とロシアを中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">8カ国共同出兵</strong></span>をやった。この事件を通じて、<strong class=\"source-bold\">イギリスはロシアへの警戒感を強めた</strong>んだ。</p>\n<p>義和団事件の時、<strong class=\"source-bold\">イギリス</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ戦争</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南ア戦争／ブール戦争</strong></span>】</strong>を戦っていたから、たいして出兵できなかったよね。かわりに日本に最大兵力を出させたけど、<ruby>鎮圧<rt>ちんあつ</rt></ruby>後も<strong class=\"source-bold\">ロシア軍は<ruby>撤退<rt>てったい</rt></ruby>せず</strong>に<strong class=\"source-bold\">満洲<ruby>占領<rt>せんりょう</rt></ruby></strong>を続けていた。ホントならイギリスは、<strong class=\"source-bold\">中国に軍隊を送ってロシアを抑え込みたい</strong>ところだったんだけど、<strong class=\"source-bold\">南ア戦争で財政難</strong>になってる……。イギリスは、またまた優先順位を考えた。「世界各地の、どこに軍隊を送るべきか？」</p>\n<blockquote><p>南アフリカ戦争での財政難は、イギリス外交が転換するポイントだよ！</p></blockquote>",
  "243": "<h2>243</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦にいたる国際関係</u></p>\n<p>まず、<strong class=\"source-bold\">最優先は「インド」</strong>だ。インドはなんとしても守る！ そして、インドに行くには<strong class=\"source-bold\">スエズ運河</strong>が重要だから「<strong class=\"source-bold\">エジプト</strong>」も守る。<strong class=\"source-bold\">南アフリカは取ったばっかり</strong>だから、捨てるわけにいかない……。「じゃあ、<strong class=\"source-bold\">中国</strong>は？」。どう考えても4番目。「こりゃ、<strong class=\"source-bold\">ほかの国に任せよう</strong>」って思った。じゃあ、誰に任せるのか？ 注目されたのが日本だ。<strong class=\"source-bold\">ロシアの進出に脅威を感じている日本と同盟</strong>を結んで、日本に極東の防衛を肩代わりしてもらおう！ってのが、イギリスの戦略。ついに<strong class=\"source-bold\">イギリス</strong>が「<strong class=\"source-bold\">光栄ある孤立</strong>」を<ruby>放棄<rt>ほうき</rt></ruby>して、<strong class=\"source-bold\">ロシアに対抗</strong>するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日英同盟</strong></span>を結んだんだ。こうして極東の日本を加えて、「<strong class=\"source-bold\"><ruby>独墺<rt>どくおう</rt></ruby>の“2”</strong>」と「<strong class=\"source-bold\">露仏の“2”</strong>」、そして「<strong class=\"source-bold\">日英の“2”……うーん、まだ1.5くらい</strong>」という状態だね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">日英同盟の成立で<ruby>列強<rt>れっきょう</rt></ruby>は3陣営に分かれ、そして<ruby>日露<rt>にちろ</rt></ruby>戦争へ！</strong></span></h4>\n<p>日英同盟が成立すると、<strong class=\"source-bold\">列強は3つのグループ</strong>になった。つまり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日英同盟</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露仏同盟</strong></span>、そして<strong class=\"source-bold\">ドイツ・オーストリア・イタリア</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国同盟</strong></span>だよ。これが、<strong class=\"source-bold\">日露戦争が始まる直前の世界情勢</strong>だ。そして1904年、イギリスと同盟した日本がロシアに<ruby>宣戦<rt>せんせん</rt></ruby>して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日露戦争</strong></span>が始まると、列強の思惑が入り乱れて国際関係が大きく変化するよ。ここで意識してほしいのは、<strong class=\"source-bold\">日露戦争</strong>は単に「日本とロシアの戦争」ってだけじゃなく、「<strong class=\"source-bold\">日英同盟 vs. 露仏同盟</strong>」の戦争になる可能性がある、ってことだ。</p>\n<h4><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\"><em data-source-italic=\"true\" style=\"font-style:italic\">日露戦争後の国際関係の変化 ［1904〜1914］</em></strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">日英同盟</strong></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><span data-source-marker=\"fill\">—</span></span></td><td><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">日</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英露協商</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">［1907］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"fill\">—</span></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露</strong></span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><strong class=\"source-bold\">独</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\">［1904］</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"fill\">—</span></span></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">仏</strong></span></td><td><strong class=\"source-bold\">墺</strong></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">↔</span></span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">三国同盟</strong></span></td><td><span data-source-marker=\"fill\">—</span></td><td><strong class=\"source-bold\">伊</strong></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露仏同盟</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"fill\">—</span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">三国協商</strong></span></td></tr></tbody></table></div>\n<blockquote><p>3つのグループだった列強が、「三国協商＋日本」と「三国同盟」の2つのグループになるよ！</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "244": "<h2>244</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">三国協商の成立</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>露仏<rt>ろふつ</rt></ruby>同盟</strong></span></span>の成立 ［1891〜94］</td><td>…… <strong class=\"source-bold\">反ドイツ</strong>でフランス・ロシアが接近</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span></span> ［1904］</td><td>…… <strong class=\"source-bold\"><ruby>日露<rt>にちろ</rt></ruby>戦争での英仏の開戦を避けるため</strong><br><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト</strong></span>、<strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モロッコ</strong></span>優先権を相互承認</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>英露<rt>えいろ</rt></ruby>協商</strong></span></span> ［1907］</td><td>……イギリスは<strong class=\"source-bold\">ドイツを警戒</strong>しロシアと同盟<br><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>イランでの対立解消、<strong class=\"source-bold\">北部をロシア、南東部をイギリス</strong>の勢力範囲とした</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国協商</strong></span></span>成立 ［1907］</td><td>…… <strong class=\"source-bold\">英露協商成立</strong>の結果、<strong class=\"source-bold\">自動的に成立</strong><br><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">イギリス、フランス、ロシア</strong>による<strong class=\"source-bold\">対ドイツ包囲網</strong>の完成<br><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>日本も、<strong class=\"source-bold\">日仏協約</strong> ［1907］、<strong class=\"source-bold\">日露協約</strong> ［1907］でフランス、ロシアと和解</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">日露戦争が始まると……ドイツに得をさせたくない英仏が接近！</strong></span></h4>\n<p>日露戦争が始まると、英仏両国はふと考えた。「この戦争、下手すると英仏が参戦しなきゃいけなくなる……」。だって、<strong class=\"source-bold\">日露戦争</strong>は「<strong class=\"source-bold\">日英同盟 vs. 露仏同盟</strong>」、<strong class=\"source-bold\">英仏の同盟国同士が戦争している</strong>んだもん。そして、<strong class=\"source-bold\">この戦争に関係ないのが三国同盟</strong>……要は<strong class=\"source-bold\">ドイツ</strong>だよ。もし英仏両国が参戦したら、戦争と関係ないドイツが「今のうちに好きなところを取っちゃえ」って進出して、戦争が終わった時に「ドイツだけが得した」って結果になるかもしれない。しかも<strong class=\"source-bold\">英仏両国はすでにファショダ事件で開戦を回避</strong>しているでしょ。今さら戦争する必要はない。</p>\n<p>こうして英仏両国は、<strong class=\"source-bold\">ドイツの台頭を警戒</strong>して、日露戦争での<strong class=\"source-bold\">英仏の開戦を回避</strong>し、<strong class=\"source-bold\">極東だけの戦争にする</strong>（難しい言葉だと「<ruby>局地化<rt>きょくちか</rt></ruby>」）ために、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span>を結んだ。この時、両国のアフリカでの利害を調整して、<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト</strong></span>、<strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モロッコ</strong></span>での優先権を相互承認したんだ。</p>\n<p>こうなると、日露戦争は英仏両国にとっては「<strong class=\"source-bold\">どっちが勝ってもいい</strong>」戦争になる。ズルいんだよ、これ。だって、もし実際の結果とは逆にロシアが勝ったとしても、<strong class=\"source-bold\">イギリスはフランスを通じてロシアを抑えられる</strong>でしょ。英仏が組んだらロシアだって文句は言えないもん。しかもフランスは、内心ではロシアが負けてもいいと思ってる！。だって、<strong class=\"source-bold\">露仏同盟</strong>は<strong class=\"source-bold\">「ドイツ」に対抗して結んだ同盟</strong>だよ。ロシアが中国に向かってもドイツにはなんの脅威にもならないから、<strong class=\"source-bold\">フランスとしてはロシアにヨーロッパに戻ってきてほしい</strong>。もちろん、英仏に組まれた</p>\n<blockquote><p>英仏協商はズルい！ 英仏は、日露戦争でどっちが勝っても損しないんだもん</p></blockquote>",
  "245": "<h2>245</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦にいたる国際関係</u></p>\n<p>ら日本だって文句は言えない。結果的に、日露戦争では<strong class=\"source-bold\">日本が勝ってロシアの極東進出が挫折</strong>したから、英仏両国の思惑通りになった、ってことね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツの脅威が現実になり、イギリスがロシアと接近！</strong></span></h4>\n<p>ちょっとだけ時代をさかのぼるよ。日露戦争中に、<strong class=\"source-bold\">ドイツ</strong>は英仏の関係を悪化させるために衝撃的な事件を起こした。だって<strong class=\"source-bold\">英仏協商にムカついた</strong>んだもん。「フランスにモロッコを取らせたくない！」と思った<strong class=\"source-bold\">ドイツ皇帝</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次モロッコ事件</strong></span>を起こすと、英仏両国は「<strong class=\"source-bold\">ドイツの脅威が現実になった</strong>！」って焦ったんだ。これは、<strong class=\"source-bold\">英仏の関係を強化</strong>しないとマズい！ 1900年ごろに<strong class=\"source-bold\">イギリスは工業生産でドイツに抜かれている</strong>から、そんなに余裕もないんだよ。</p>\n<p>一方、<strong class=\"source-bold\">イギリス</strong>にとってロシアは、もはや脅威じゃない。むしろ、<strong class=\"source-bold\">ドイツに対抗</strong>するなら、<strong class=\"source-bold\">ロシアは味方にしたほうが得</strong>だよ。だって挟み撃ちにできるでしょ。そして、<strong class=\"source-bold\">ロシアもイギリスと同盟したほうが得</strong>になったんだよ。東アジアで挫折した<strong class=\"source-bold\">ロシア</strong>はもう一度<strong class=\"source-bold\">バルカン半島に進出したい</strong>から、<strong class=\"source-bold\">オーストリアやドイツとの対立</strong>は避けられない。しかも、英仏が同盟したから、イギリスは敵にできないんだもん。</p>\n<p>こうして1907年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英露協商</strong></span>が成立したよ。これで、すでにある<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">露仏同盟</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span>とあわせて、<strong class=\"source-bold\">自動的に</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">三国協商</strong></span>が成立したんだ。この3国はすべてドイツと対立しているから、<strong class=\"source-bold\">三国協商はドイツ包囲網</strong>だね。そして、イギリスと同盟している日本も、1907年に<strong class=\"source-bold\">日仏協約、日露協約</strong>を結び、日露戦争前に3グループに分かれていた<ruby>列強<rt>れっきょう</rt></ruby>は、「<strong class=\"source-bold\">三国協商＋日本</strong>」と「<strong class=\"source-bold\">三国同盟</strong>」の2つのグループになったんだ。</p>\n<blockquote><p>三国協商は「自動的に」できたんだよ。三国協商条約みたいなものはないからね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">第2次モロッコ事件で、英仏VS.ドイツの対立が激化！</strong></span></h4>\n<p>三国協商が成立すると、<strong class=\"source-bold\">イギリスとドイツの関係はどんどん悪化</strong>し、お互いに海軍を大拡張する<ruby>建艦<rt>けんかん</rt></ruby>競争を繰り広げた。そして、1911年にはドイツがモロッコに軍艦を派遣する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次モロッコ事件</strong></span>が起きたよね。この時イギリスは海軍の出動を準備し、フランスも国内の反ドイツ世論が盛り上がって、<strong class=\"source-bold\">結果的に「英仏 vs. ドイツ」の対立が激化</strong>した。こうなると、両陣営の戦争がいつ始まってもおかしくない。<strong class=\"source-bold\">各国は戦争準備のために軍備の拡大を進め</strong>、このままだと次に戦争が起きたら確実に大戦争になる。この時期のヨーロッパは、戦争は起きてないけどいつでも戦争が可能な「<strong class=\"source-bold\">武装平和</strong>」の状態になっていた。あとは、きっかけがあれば開戦しちゃうよ。そして、危機は<strong class=\"source-bold\">バルカン半島</strong>で起きたんだ。</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "246": "<h2>246</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">「ヨーロッパの火薬庫」</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">盛り上がるナショナリズム。バルカンは爆発寸前の「火薬庫」だ！</strong></span></h4>\n<p><strong class=\"source-bold\">バルカン半島</strong>では、<strong class=\"source-bold\">オーストリアやロシア</strong>が小国のナショナリズムを利用して、ドサクサに紛れて勢力拡大を狙っていた。これが「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パン＝スラヴ主義</strong></span>」と「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パン＝ゲルマン主義</strong></span>」だよ。</p>\n<p>「パン＝○○」っていうのは、「○○の連携」くらいの意味だったよね。じゃあ、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パン＝スラヴ主義</strong></span>」ってなんだろう？ 表向きは「バルカン半島の<strong class=\"source-bold\">スラヴ人はギリシア正教徒が多い</strong>から、同じ<strong class=\"source-bold\">ギリシア正教のロシア</strong>を中心にスラヴ人が連携しましょう」っていう主張だ。で、ウラに隠れてるのは<strong class=\"source-bold\">ロシアの言い訳</strong>。<strong class=\"source-bold\">ロシアはセルビアを支援</strong>して、「セルビアを助けてるだけだよ」って言いながら、<strong class=\"source-bold\">勢力拡大を狙った</strong>んだ。だって、イギリスと同盟国になったロシアが、バルカン半島にガンガン進出するわけにいかないでしょ？</p>\n<p>じゃあ、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パン＝ゲルマン主義</strong></span>」は？ ゲルマンっていうのは「<strong class=\"source-bold\">ジャーマン（German）</strong>」、つまり<strong class=\"source-bold\">ドイツ人</strong>だから、「<strong class=\"source-bold\">ドイツ帝国のもとに全ゲルマン（ドイツ）民族が結集</strong>して、世界の<ruby>覇権<rt>はけん</rt></ruby>を握ろう」って主張だ。要するに「<strong class=\"source-bold\">ドイツ帝国とオーストリア帝国が手を組んでバルカン進出</strong>する」ってことね。これは、ヴィルヘルム2世の「世界政策」や、オーストリアのバルカン進出の口実になったんだよ。</p>\n<h4><strong class=\"source-bold\">〈第一次世界大戦直前のバルカン半島〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア帝国</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ボスニア・ヘルツェゴヴィナ併合</span></td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"outline-arrow\">⇨</span></span></td></tr><tr><td><strong class=\"source-bold\">ルーマニア</strong></td><td><span data-source-marker=\"dashed-arrow\">······</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↓</span></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↙ ↓ ↘</span></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンテネグロ</strong></span></span></td><td>イスタンブル</td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア</strong></span></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">↘</span></span></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></td><td><span data-source-marker=\"point\">◯</span></td></tr><tr><td><span data-source-pattern=\"hatching\" style=\"background:repeating-linear-gradient(45deg,transparent,transparent 3px,#315837 3px,#315837 4px)\">▧</span> 第1次バルカン戦争直前のオスマン帝国領</td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">国名</strong></span></span> バルカン同盟の加盟国</td></tr></tbody></table></div>\n<blockquote><p>「セルビア、ロシア」vs.「ドイツ、オーストリア」の対立を意識しながら見てね！</p></blockquote>",
  "247": "<h2>247</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">「ヨーロッパの火薬庫」</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">オスマン帝国の弱体化に乗じて、各国の進出と自立が進んだ！</strong></span></h4>\n<p>1908年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">青年トルコ革命</strong></span>が起こると、各国の動きが活発になった。まず、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>が<strong class=\"source-bold\">独立</strong>して、さらに<strong class=\"source-bold\">オーストリア</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボスニア・ヘルツェゴヴィナ</strong></span>を<ruby>併合<rt>へいごう</rt></ruby>したよ。オーストリアの進出だから「<strong class=\"source-bold\">パン＝ゲルマン主義</strong>」だ。そしたら<strong class=\"source-bold\">ロシアの支援を受けたセルビア（パン＝スラヴ主義ね）</strong>が、「セルビア人の住んでるところは全部併合する！」っていう<strong class=\"source-bold\">大セルビア主義</strong>を主張して、<strong class=\"source-bold\">オーストリアに反発</strong>した。ボスニアにはセルビア人が多かったからね。</p>\n<p>さらに、<strong class=\"source-bold\">第2次モロッコ事件</strong>で「英仏 vs. 独の戦争が起きるかもしれない！」という<strong class=\"source-bold\">国際的な緊張</strong>が高まると、ドサクサに紛れて<strong class=\"source-bold\">イタリア</strong>がオスマン帝国（トルコ）と開戦！ この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア＝トルコ戦争</strong></span>に勝利したイタリアは、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリポリ・キレナイカ</strong></span>を植民地にして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リビア</strong></span>と改称した。このウラには、<strong class=\"source-bold\">フランスとイタリアの密約</strong>がある！。1902年、フランスはイタリアに謝った。「チュニジア取っちゃってごめんね〜。かわりにリビアあげるね。だから、ドイツの味方しちゃダメだよ」ってね。イタリアは感動。こうして<strong class=\"source-bold\">仏伊協商</strong>が成立し、独仏戦争が始まっても<strong class=\"source-bold\">イタリアがドイツ側で参戦しない</strong>かわりに、<strong class=\"source-bold\">イタリアのトリポリ・キレナイカ、フランスのモロッコ</strong>優先権を相互承認したんだ。</p>\n<blockquote><p>イタリアがリビアを取っても、英仏が怒らなかったのは、ドイツの味方をしないからだよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">オスマン帝国から領土を奪え！ 2次にわたるバルカン戦争が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p><strong class=\"source-bold\">イタリア＝トルコ戦争でオスマン帝国が劣勢</strong>になったのを見て、「今のうちに領土を奪え〜！」って、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モンテネグロ</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ギリシア</strong></span>の4国が、<strong class=\"source-bold\">ロシアの指導</strong>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルカン同盟</strong></span>を結成したよ。これは、ロシアがスラヴ人の国を結集させたから「<strong class=\"source-bold\">パン＝スラヴ主義</strong>」だ（ギリシアはスラヴ人じゃないけど、ギリシア正教だ）。そして<strong class=\"source-bold\">バルカン同盟 vs. オスマン帝国</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次バルカン戦争</strong></span>が始まったんだ。</p>\n<h4><strong class=\"source-bold\">〈第1次バルカン戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong></span></td><td><span data-source-marker=\"fill\">＝</span></td><td><strong class=\"source-bold\">〈バルカン同盟〉</strong><br><strong class=\"source-bold\">セルビア</strong><br><strong class=\"source-bold\">ブルガリア</strong><br><strong class=\"source-bold\">モンテネグロ</strong><br><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">パン＝スラヴ主義</strong></span></td><td><span data-source-marker=\"arrow\">↑</span></td><td><span data-source-marker=\"outline-arrow\">⇨</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">オスマン帝国<br>（親ドイツ・反ロシア）</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">←</span></span></td><td><span data-source-marker=\"fill\">＝</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">オーストリア</span></td><td><span data-source-marker=\"arrow\">↑</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">パン＝ゲルマン主義</span></td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "248": "<h2>248</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>この時<strong class=\"source-bold\">オスマン帝国（トルコ）</strong>は、バルカン同盟の中心<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セルビア</strong></span>と、それを支援する<strong class=\"source-bold\">ロシアに反発してオーストリアに接近</strong>した。オーストリアの進出の口実が<strong class=\"source-bold\">パン＝ゲルマン主義</strong>だから、第1次バルカン戦争は「<strong class=\"source-bold\">パン＝スラヴ主義 vs. パン＝ゲルマン主義</strong>」の戦争ともいわれるよ。</p>\n<p>敗れた<strong class=\"source-bold\">オスマン帝国</strong>は、<strong class=\"source-bold\">バルカン半島の大半の領土を失った</strong>んだけど、バルカン戦争はこれで終わらなかったんだよ。オスマン帝国から奪った領土の分配をめぐって、バルカン同盟で内紛が起きた。この戦争で<strong class=\"source-bold\">ギリシア</strong>は「ギリシア文明発祥の地だ〜」って<strong class=\"source-bold\">クレタ島</strong>を<ruby>占領<rt>せんりょう</rt></ruby>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブルガリア</strong></span>は「オレが一番たくさん<strong class=\"source-bold\">領土をもらう</strong>！」って言ったの。これに反発した<strong class=\"source-bold\">セルビア</strong>は、「オマエばっかり領土取ってんじゃないよ」と怒って、ギリシアやモンテネグロと組んで、<strong class=\"source-bold\">ブルガリアに戦争を吹っ掛けた</strong>んだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次バルカン戦争</strong></span>だよ。</p>\n<h4><strong class=\"source-bold\">〈第2次バルカン戦争〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong></span></td><td><span data-source-marker=\"fill\">＝</span></td><td><strong class=\"source-bold\">セルビア</strong><br><strong class=\"source-bold\">モンテネグロ</strong><br><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ルーマニア</strong></span></td><td><span data-source-marker=\"fill\">＝</span></td><td><span data-source-border=\"black\" style=\"border:2px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></span></td></tr><tr><td><span data-source-marker=\"outline-arrow\">⇨</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"arrow\">←</span></span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">ブルガリア</span></td></tr><tr><td><span data-source-marker=\"dashed-arrow\">······</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">オーストリア</span></td><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\">ブルガリアがオーストリアに接近</span></td></tr></tbody></table></div>\n<p>この戦争でも、やはり<strong class=\"source-bold\">ロシアはセルビアの味方</strong>をした。さらに、ブルガリアの北からは「ドサクサに紛れて領土を取っちゃえ！」って思っている<strong class=\"source-bold\">ルーマニア</strong>が参戦し、<strong class=\"source-bold\">オスマン帝国</strong>も「ちょっとでもいいから領土を取り返そう」ってブルガリアに攻め込んできた。こうして<strong class=\"source-bold\">ブルガリアが多くの領土を奪われた</strong>んだ。</p>\n<p>そして、2回のバルカン戦争を通じて<strong class=\"source-bold\">国際関係が変化</strong>したよ。敗北した<strong class=\"source-bold\">オスマン帝国とブルガリアはセルビアにムカついてる</strong>。でも、<strong class=\"source-bold\">セルビアにはロシアがついてる</strong>よね。ロシアに対抗できそうな大国といえば、バルカン半島では<strong class=\"source-bold\">オーストリア</strong>、そしてその同盟国<strong class=\"source-bold\">ドイツ</strong>だ。こうして、<strong class=\"source-bold\">オスマン帝国とブルガリア</strong>は反セルビア・反ロシアで<strong class=\"source-bold\">ドイツ・オーストリアに接近</strong>したから、<strong class=\"source-bold\">セルビアとオーストリアの対立</strong>が激化し、双方の同盟国である<strong class=\"source-bold\">三国協商（英・仏・露）とドイツ・オーストリア</strong>の対立まで激化して、いつ戦争になってもおかしくない状況になった。ちょっとの火花で爆発する「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヨーロッパの火薬庫</strong></span>」だ！</p>\n<blockquote><p>これでヨーロッパは、いつ戦争が起きてもおかしくない状態になっちゃった</p></blockquote>",
  "249": "<h2>249</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">サライェヴォの一発の銃声が、世界大戦を引き起こした！</strong></span></h4>\n<p>1914年6月28日、陸軍の演習のためにボスニアを訪問していた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリアの帝位継承者</strong></span><strong class=\"source-bold\">フランツ＝フェルディナント</strong>夫妻が、<strong class=\"source-bold\">ボスニアの州都</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サライェヴォ</strong></span>で<strong class=\"source-bold\">セルビア人</strong>によって暗殺された。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サライェヴォ事件</strong></span>をきっかけに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オーストリアがセルビアに<ruby>宣戦<rt>せんせん</rt></ruby></strong></span>したんだけど、これがとんでもない戦争に発展するんだ。</p>\n<p>まず、<strong class=\"source-bold\">セルビアを支援</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア</strong></span>が<strong class=\"source-bold\">総動員令</strong>を発すると、ロシアに対抗して<strong class=\"source-bold\">ドイツがロシアに宣戦</strong>、続いてロシアの同盟国<strong class=\"source-bold\">フランスにも宣戦</strong>した。そして、ドイツ軍がフランスに攻めこむ際に、<strong class=\"source-bold\">ベルギーの中立を<ruby>侵犯<rt>しんぱん</rt></ruby></strong>したことを口実に、<strong class=\"source-bold\">イギリスもドイツに宣戦</strong>した。こうして、<strong class=\"source-bold\">独・墺（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">同盟国</strong></span>）vs.露・仏・英（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">連合国</strong></span>・協商国）</strong>が開戦して、サライェヴォの銃声から約1カ月、開戦からわずか1週間のうちに、ほぼヨーロッパ全域を巻き込む<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第一次世界大戦</strong></span>に発展してしまったんだよ。</p>\n<h4><strong class=\"source-bold\">＋<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">α</strong></span>ちょっと寄り耳</strong> <span data-source-marker=\"arrow\">⤴</span></h4>\n<blockquote><p>サライェヴォで銃声が鳴った瞬間、「世界大戦になる」って思った人はほとんどいなかった。でも偶然が重なり合って、気づけば世界大戦になったんだ。</p>\n<p>1914年6月28日、サライェヴォ駅からオープンカーで市庁舎に向かうオーストリアの帝位継承者フランツ＝フェルディナント大公夫妻に、一発の爆弾が投げつけられた。ここでは事なきを得た大公は、市長に「爆弾で歓迎されるとは意外だ」とイヤミを言ったんだけど、その後、市庁舎を出た大公夫妻の車が一瞬止まった時に、セルビア人学生のプリンチップが至近距離から2発ピストルを撃ち、大公夫妻は亡くなった。</p>\n<p>この時、オーストリア政府では「対立しているセルビアを、この機会に<ruby>潰<rt>つぶ</rt></ruby>そう！」っていう意見が強まったんだけど、ロシアの動きが気になってドイツに確認をとった。するとドイツは「こっちが強硬に出れば、ロシアもフランスも動かないだろう」って根拠のない予測から、オーストリアを全面的に支持したんだ。だから、オーストリアは内政<ruby>干渉<rt>かんしょう</rt></ruby>（例えば、セルビア国内の裁判にオーストリア政府を参加させる、など）まで要求する最後<ruby>通牒<rt>つうちょう</rt></ruby>を送ったんだね。</p>\n<p>これに対してセルビアは、内政干渉の部分以外はほぼ全面的に屈服したから、世界中は「戦争は回避した！」って思ったんだけど、「これでは不十分だ」としてオーストリアがセルビアに宣戦したんだ。まさかの展開……！。ここから各国が次々参戦して、第一次世界大戦に発展したんだよ。</p></blockquote>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">第一次世界大戦</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツの秘策が失敗。短期決戦のはずが、長期化する予感……</strong></span></h4>\n<p>いざ開戦してしまうと、不利なのは<strong class=\"source-bold\">ドイツ</strong>だよね。だって、<strong class=\"source-bold\">フランスとロシアに挟み撃ちされる</strong>……。しかし、ドイツには秘策「<strong class=\"source-bold\">シュリーフェン＝プラン</strong>」があっ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "250": "<h2>250</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>た。どうせロシア軍はダラダラと準備が遅いから、最初にフランスに総攻撃をかけて<ruby>潰<rt>つぶ</rt></ruby>して、そのあとに急いで東部戦線に大軍を戻して、遅れてきたロシアを<ruby>叩<rt>たた</rt></ruby>く、って計画だ。まあ、半年くらいの短期決戦の予定だったんだけど……。</p>\n<p>まず、予想外に<strong class=\"source-bold\">ロシアが早かった</strong>！。ドイツ軍は、一気にベルギーを突破してパリまで40キロに迫ったから、「もうフランスには勝てたな」と判断して、軍団をロシア方面に送った。そしたら、ロシア軍も予想外に早くドイツに<ruby>侵入<rt>しんにゅう</rt></ruby>していて、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東部戦線</strong></span>ではいきなり<strong class=\"source-bold\">独露両軍が<ruby>衝突<rt>しょうとつ</rt></ruby></strong>したんだ。この<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンネンベルクの戦い</strong></span>は、準備が遅れていたにもかかわらず、<strong class=\"source-bold\">ヒンデンブルク</strong>率いる<strong class=\"source-bold\">ドイツ軍がロシア軍を破った</strong>。ところが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西部戦線</strong></span>では、態勢を立て直したフランス軍が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルヌの戦い</strong></span>で<strong class=\"source-bold\">ドイツ軍を<ruby>撃退<rt>げきたい</rt></ruby></strong>したんだけど、大量使用された<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">機関銃</strong></span>の威力で両軍で25万人もの死傷者を出したため、<strong class=\"source-bold\">戦線が<ruby>膠着<rt>こうちゃく</rt></ruby></strong>してしまった。要は「<strong class=\"source-bold\">どっちも動けない</strong>」。</p>\n<p>こうして、ドイツは<strong class=\"source-bold\">東部・西部の二正面での戦争</strong>をすることとなり、連合国・同盟国がどちらも決定的な勝利を得られないまま、<strong class=\"source-bold\">戦争は長期化</strong>し始めたんだよ。だって、相手の攻撃から身を守るために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>塹壕戦<rt>ざんごうせん</rt></ruby></strong></span>（隠れる溝を掘って、そこに兵士がずっと待機する）になり、ひたすら<strong class=\"source-bold\">機関銃を撃ち続けた</strong>。こうなると、国内では弾丸を生産し続けないといけないし、兵士の食糧も生産しないといけない。何よりもまず、兵士の人数が足りない。各国は<strong class=\"source-bold\">国力のすべてを戦争に動員</strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">総力戦</strong></span>を戦うことになり、<strong class=\"source-bold\"><ruby>挙国一致<rt>きょこくいっち</rt></ruby>体制</strong>がつくられたんだ。</p>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ユトランド沖</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"battle\">⚔</span></span></td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">ロシア</strong></span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">イギリス</strong></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">タンネンベルク</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"battle\">⚔</span></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ソンム</span></td><td><strong class=\"source-bold\">ドイツ帝国</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">東部戦線</strong></span></td></tr><tr><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">マルヌ</span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">西部戦線</strong></span></td><td><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ヴェルダン</span></td></tr><tr><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">フランス</strong></span></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"battle\">⚔ ⚔ ⚔</span></span></td><td><strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong></td></tr><tr><td><strong class=\"source-bold\">ポルトガル</strong></td><td><strong class=\"source-bold\">セルビア</strong></td><td><strong class=\"source-bold\">ルーマニア</strong></td></tr><tr><td><strong class=\"source-bold\">イタリア</strong></td><td><strong class=\"source-bold\">ブルガリア</strong></td><td><strong class=\"source-bold\">ギリシア</strong></td></tr><tr><td><strong class=\"source-bold\">オスマン帝国（トルコ）</strong></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"dashed-arrow\">······</span></span></td><td><span data-source-marker=\"dashed-arrow\">--- ---</span></td></tr></tbody></table></div>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"fill\">■</span></span> 同盟国側</td><td><span data-source-color=\"green\" style=\"color:#315837\"><span data-source-marker=\"fill\">■</span></span> 連合国側</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"battle\">⚔</span></span> おもな戦い</td><td><span data-source-border=\"black\" style=\"border:1px solid #001000;padding:0 0.2em\"><strong class=\"source-bold\">国名</strong></span> 三国協商</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><span data-source-marker=\"dashed-arrow\">······</span></span> 1917年のドイツ軍の前線</td><td></td></tr><tr><td><span data-source-marker=\"dashed-arrow\">--- ---</span> ブレスト＝リトフスク条約［1918］による国境線</td><td></td></tr></tbody></table></div>",
  "251": "<h2>251</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第一次世界大戦</u></p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">日本やイタリアも連合国側で参戦！ さらに、新兵器も登場</strong></span></h4>\n<p>開戦直後の1914年8月、<strong class=\"source-bold\">日英同盟を口実</strong>にして<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本が参戦</strong></span>し、<strong class=\"source-bold\">ドイツ領南洋諸島</strong>（南太平洋の島々）や中国での<strong class=\"source-bold\">ドイツの<ruby>租借地<rt>そしゃくち</rt></ruby></strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>膠州湾<rt>こうしゅうわん</rt></ruby></strong></span>を<ruby>占領<rt>せんりょう</rt></ruby>した。日本の軍事行動は<strong class=\"source-bold\">14年中にすべて終わり</strong>、1915年には中国の<ruby>袁世凱<rt>えんせいがい</rt></ruby>政権に対して、<strong class=\"source-bold\">ドイツの持っていた権益の譲渡</strong>などを求める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">二十一カ条要求</strong></span>を提出したよ。</p>\n<p>さらに1915年になると、<strong class=\"source-bold\">中立を宣言していた</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア</strong></span>が<strong class=\"source-bold\">連合国（三国協商側）で参戦</strong>した。これね、「連合国側で参戦したら<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>未回収<rt>みかいしゅう</rt></ruby>のイタリア</strong></span>を返してあげるよ」っていうイギリスの誘いにイタリアが乗ったんだよ（<strong class=\"source-bold\">ロンドン秘密条約</strong>）。</p>\n<p>そして第一次世界大戦では、いろんな<strong class=\"source-bold\">新兵器が登場</strong>した。塹壕を乗り越える<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">戦車</strong></span>、さらにドイツ軍が<strong class=\"source-bold\">イープルの戦い</strong>で初めて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">毒ガス</strong></span>を使ったんだ。偵察用に使われた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">飛行機</strong></span>も、徐々に攻撃にも使われるようになった。また、すでに発明されていた兵器のうち、海では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">潜水艦</strong></span>が、陸上では<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">機関銃</strong></span>が本格的に使われるようになった。こうした兵器の使用によって、多数の戦死者を出すことになったんだよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">1916年には両陣営が大攻勢！ しかし決着はつかず</strong></span></h4>\n<p>戦線がほとんど動かないまま1916年に突入すると、各国では強力な戦時体制（英は<strong class=\"source-bold\">ロイド＝ジョージ</strong>、仏は<strong class=\"source-bold\">クレマンソー</strong>の挙国一致内閣、独は<strong class=\"source-bold\">軍部独裁体制</strong>）がつくられ、状況をなんとか打ち破ろうと、<strong class=\"source-bold\">西部戦線</strong>では<strong class=\"source-bold\">ドイツ軍</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルダン<ruby>要塞<rt>ようさい</rt></ruby></strong></span>に猛攻撃をかけたんだ。ここを突破すればパリが見えてくる！ と思ったんだけど、<strong class=\"source-bold\">ペタン</strong>の率いる<strong class=\"source-bold\">フランス軍は、要塞を守り切った</strong>。この戦闘での両軍の死者はおよそ70万人！ 特に死者が多かったフランスにとって「<strong class=\"source-bold\">ヴェルダン＝第一次世界大戦</strong>」というくらいの衝撃だったんだよ。一方、英仏を中心とする連合軍も、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソンム</strong></span>で<strong class=\"source-bold\">ドイツ軍に大攻勢</strong>をかけたよ。この戦闘では<strong class=\"source-bold\">イギリス軍が初めて戦車を使用</strong>し、両軍合わせて約2000万発ともいわれる砲弾が使用されたんだけど<strong class=\"source-bold\">決着はつかず</strong>、約150万人ともいわれる戦死者を出した。さらに海軍では、<strong class=\"source-bold\">ユトランド沖海戦</strong>でイギリスとドイツが衝突し、大きな被害を受けたドイツは、「軍艦よりも<strong class=\"source-bold\">潜水艦で連合軍の船を撃沈したほうがいい</strong>！」として、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">無制限潜水艦作戦</strong></span>に向かっていったんだ。</p>\n<h4><strong class=\"source-bold\">〈第一次世界大戦の主な戦い〉</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>戦線</td><td>西部戦線</td><td></td><td>東部戦線</td></tr><tr><td></td><td>英・仏</td><td>ドイツ</td><td>ロシア</td></tr><tr><td>1914年</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マルヌの戦い</strong></span><br>○フランス vs. ×ドイツ</td><td></td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンネンベルクの戦い</strong></span><br>○ドイツ vs. ×ロシア</td></tr><tr><td>1916年</td><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴェルダン要塞の攻防戦</strong></span><br>○フランス vs. ×ドイツ<br><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソンムの戦い</strong></span><br>△英仏 vs. △ドイツ</td><td></td><td>軍備の貧弱なロシアが劣勢</td></tr></tbody></table></div>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "252": "<h2>252</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">戦局を変えたのは、世界1位の大国になったアメリカの参戦だ！</strong></span></h4>\n<p>1915年に起きた<strong class=\"source-bold\">ルシタニア号事件</strong>（イギリス船がドイツの潜水艦に<ruby>撃沈<rt>げきちん</rt></ruby>されて、アメリカ人128名が死亡した事件）をきっかけに<strong class=\"source-bold\">ドイツに対する強硬論</strong>が巻き起こっていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカ</strong></span>は、1917年に<strong class=\"source-bold\">ドイツ</strong>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">無制限潜水艦作戦</strong></span>を開始すると、<strong class=\"source-bold\">これを口実に参戦した</strong>んだ。ちなみに、1917年に<strong class=\"source-bold\">石井・ランシング協定</strong>を結んで、<strong class=\"source-bold\">日本の中国における特殊権益</strong>と、<strong class=\"source-bold\">アメリカの中国への機会均等</strong>を相互承認したのは、アメリカがヨーロッパに<ruby>介入<rt>かいにゅう</rt></ruby>する前に<strong class=\"source-bold\">日米関係を調整しておきたいと思った</strong>からだよ。こうして<strong class=\"source-bold\">世界一の工業国</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アメリカが連合国側で参戦</strong></span>すると、ドイツを中心とする同盟国側は劣勢になっていったんだ。ただ、連合国側でも<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア革命</strong></span>後の1918年に結ばれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレスト＝リトフスク条約</strong></span>でドイツとロシアの講和が実現し、<strong class=\"source-bold\">ロシアが戦争から脱落</strong>したため<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.256</span>、ドイツは西部戦線に集中できるようになった。</p>\n<p>そして<strong class=\"source-bold\">イギリス</strong>は、戦争を有利にするための<strong class=\"source-bold\">秘密外交を進めていた</strong>。まず1915年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">フセイン・マクマホン協定</strong></span>を結んで、<strong class=\"source-bold\">アラブ人の対オスマン帝国（トルコ）参戦</strong>を条件に、戦後の<strong class=\"source-bold\">アラブ人の独立</strong>を約束した。それにもかかわらず、1916年には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">サイクス・ピコ協定</strong></span>を結んで、<strong class=\"source-bold\">オスマン帝国領を英・仏・露の3国で分割</strong>することを決めちゃった。さらに、<strong class=\"source-bold\">ユダヤ系金融資本のロスチャイルド家の戦争協力</strong>を得るため、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">バルフォア宣言</strong></span>で戦後の<strong class=\"source-bold\">ユダヤ人の建国</strong>を支持した（「民族的郷土（National Home）」って書いてあるけど……）。これって、パレスチナっていう同じ場所を含む約束だから、<strong class=\"source-bold\">同時に実現するのは不可能</strong>。これがのちに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パレスチナ問題</strong></span>を引き起こすよ。</p>\n<blockquote><p>イギリスの秘密外交は、のちにパレスチナ問題を引き起こす原因だよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツでも革命が起きて……4年にわたる戦争がやっと終わった！</strong></span></h4>\n<p>1918年になると、<strong class=\"source-bold\">ドイツを中心とする同盟国側は追いつめられていった</strong>。だって英仏側には、<strong class=\"source-bold\">アメリカからどんどん武器や兵士が送られてくる</strong>んだもん。しかも、アメリカ軍は兵士だけじゃなく<strong class=\"source-bold\">インフルエンザ</strong>まで持ってきた！ 当時、<strong class=\"source-bold\">スペイン風邪</strong>と呼ばれたのは、中立国だったスペインだけがこの感染症を報道していたからだ。各国は軍内部での感染を隠していたけど、<strong class=\"source-bold\">インフルエンザの大流行でもはや軍は身動きが取れなくなった</strong>んだ。同盟国側は弱い国から脱落していき、9月に<strong class=\"source-bold\">ブルガリア</strong>、10月に<strong class=\"source-bold\">オスマン帝国</strong>、さらに<strong class=\"source-bold\">オーストリア＝ハンガリー帝国</strong>が降伏すると、戦っているのは<strong class=\"source-bold\">ドイツだけ</strong>になったんだ。</p>\n<p>ドイツでも、11月に入って<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">キール軍港の水兵反乱</strong></span>が起き、これを機に全国に反乱が拡大！ 各地で<strong class=\"source-bold\">労働者と兵士がレーテ</strong>（評議会）を結成して<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ革命</strong></span>に発展したよ。11月9日には<strong class=\"source-bold\">ヴィルヘルム2世が退位してオランダに<ruby>亡命<rt>ぼうめい</rt></ruby></strong>し、ベルリンでは共和政が宣言された（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ共和国</strong></span>）。そして、11月11日、フランスのコンピエーニュの森で<strong class=\"source-bold\">休戦条約（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ドイツ休戦協定</strong></span>）が結ばれて</strong>、4年におよぶ第一次世界大戦</p>",
  "253": "<h2>253</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア革命</u></p>\n<p><strong class=\"source-bold\">は終結した</strong>んだ。この戦争での死者は<strong class=\"source-bold\">ドイツ軍だけでも200万人以上</strong>、連合国・同盟国を合わせると<strong class=\"source-bold\">900万人以上</strong>。これまでとはケタが違う大戦争だな。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ロシア革命</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">ロシア革命の流れ</strong></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">二月革命</strong></span></span>（西暦では<strong class=\"source-bold\">三月革命</strong>）［1917.3］</td><td>…… <strong class=\"source-bold\">ブルジョワ革命とされる</strong></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペトログラード<ruby>蜂起<rt>ほうき</rt></ruby></strong></span>［1917.3.8］</td><td>……全市の労働者のゼネストに発展</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span><strong class=\"source-bold\">が退位</strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロマノフ朝滅亡</strong></span> ［1917.3.15］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><strong class=\"source-bold\">二重権力状態</strong></td><td>……臨時政府とソヴィエトが<ruby>並存<rt>へいそん</rt></ruby></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">臨時政府</strong></span></td><td>…… <strong class=\"source-bold\">ブルジョワジー</strong>が中心　<span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">戦争継続</strong>政策をとる</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト</strong></span></td><td>…… <strong class=\"source-bold\">労働者と兵士</strong>の評議会　<span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">停戦</strong>を求める</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span></span>の帰国 ［1917.4］</td><td>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ</strong></span>の指導者</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><strong class=\"source-bold\">四月テーゼ</strong>［1917.4］</td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">“すべての権力をソヴィエトへ”</strong>がスローガン</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケレンスキー</strong></span></span>内閣成立 ［1917.7］</td><td>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span>】</strong>のケレンスキーが首相となる</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">臨時政府は戦争継続</strong>の方針を変えず</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span>コルニーロフの反政府反乱［1917.9］</td><td>……ボリシェヴィキの協力で<ruby>鎮圧<rt>ちんあつ</rt></ruby></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">ボリシェヴィキへの支持拡大</strong>。レーニンの再帰国 ［1917.10］</td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月革命</strong></span></span>（西暦では<strong class=\"source-bold\">十一月革命</strong>）［1917.11.7］</td><td>…… <strong class=\"source-bold\">社会主義革命とされる</strong></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">ボリシェヴィキ派の労働者や兵士</strong>が武装蜂起</td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">臨時政府の打倒</strong></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">●</span><strong class=\"source-bold\">全ロシア＝ソヴィエト会議</strong> ［1917.11.8］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong></span>」</td><td>…… “<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無併合<rt>むへいごう</rt></ruby>・無償金</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無賠償<rt>むばいしょう</rt></ruby></strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">・民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>”の3原則での講和を提示</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">土地に関する布告</strong></span>」</td><td>…… <strong class=\"source-bold\">土地私有権を廃止</strong>する布告</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">憲法制定会議</strong>選挙（<strong class=\"source-bold\">ロシア初の普通選挙</strong>）の実施 ［1917.11.25］</td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\">▶</span><strong class=\"source-bold\">エスエルが圧勝</strong>。ボリシェヴィキは第2党</td><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span>開会 ［1918.1.18］</td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><strong class=\"source-bold\">ボリシェヴィキが憲法制定会議を武力で閉鎖・解散</strong></td><td></td></tr><tr><td><span data-source-color=\"gray\" style=\"color:#777777\"><span data-source-marker=\"arrow\">→</span></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ<ruby>独裁<rt>どくさい</rt></ruby></strong></span>（一党支配）確立 ［1918.1.19］</td><td></td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">戦争の長期化で国民生活が悪化したロシアでは、二月革命が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p>続いて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア革命</strong></span>について見ていくよ。もともと産業の基盤が強くなかったロシアでは、<strong class=\"source-bold\">第一次世界大戦が始まると国民生活が一気に悪化</strong>したよ。だって、日露戦争の時にも食糧難が起きていたでしょ？ 第一次世界大戦は日露戦争よりもずっと大規模だったから、ロシアでの食糧や燃料などの物資不足は深刻だったんだよ。し</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "254": "<h2>254</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>かも、ショボい装備しかない<strong class=\"source-bold\">ロシア軍は大敗を続け</strong>、兵士の間にも「戦争はイヤだ〜」って意識が広がっていたんだ。</p>\n<p>こんな状態なのに、皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span>は相変わらずなんだよ……。息子（皇太子）アレクセイの病気が一番の心配事。ついでに皇后（つまり奥さんね）も息子にしか興味がない。怪僧<strong class=\"source-bold\">ラスプーチン</strong>のあやしい催眠療法で息子アレクセイの体調がたまたま良くなったから、皇后がラスプーチンの言うことならなんでも聞くようになり、皇帝もそれに流された。1916年に殺されるまで、ラスプーチンが宮廷を動かしたから、ロシアの政治は大混乱だ。首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペトログラード</strong></span>（「<strong class=\"source-bold\">ペテルブルク（ドイツ語）</strong>」の<strong class=\"source-bold\">ロシア語読み</strong>。大戦でドイツが敵になったから、名前が変わったよ）では<strong class=\"source-bold\">食糧難が起こり</strong>、民衆のなかには「革命起こそう！」って言い出すヤツまで現れていた。そして1917年、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">二月革命</strong></span>（西暦では<strong class=\"source-bold\">三月革命</strong>）が<ruby>勃発<rt>ぼっぱつ</rt></ruby>したんだ。</p>\n<p>国際婦人デーである2月23日（西暦では3月8日。正教国のロシアではユリウス暦を使用）の朝、首都<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ペトログラード</strong></span>の<strong class=\"source-bold\">女性労働者</strong>たちは、一斉に「パンよこせ〜」って立ち上がった！ さらに「おかーちゃんが<ruby>頑張<rt>がんば</rt></ruby>ってるなら、オレも行くぜ」と<strong class=\"source-bold\">男性労働者もデモに合流</strong>して、全市を巻き込むゼネストになった。すると、<ruby>鎮圧<rt>ちんあつ</rt></ruby>を命じられた<strong class=\"source-bold\">兵士たち</strong>まで「オレたちも食べ物がないんだよ」と<strong class=\"source-bold\">デモに合流</strong>し始め、<strong class=\"source-bold\">労働者と兵士の代表</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">評議会・労兵会</strong></span>】</strong>が結成されたよ。一方、<strong class=\"source-bold\">ドゥーマ</strong>（帝政ロシア国会）を中心に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">臨時政府</strong></span>がつくられたけど、<strong class=\"source-bold\">下級の兵士たちはもちろんソヴィエトに忠誠を誓った</strong>。もはや革命が収まらないと思った臨時政府は、<strong class=\"source-bold\">ニコライ2世に退位を要求</strong>！。ニコライ2世は弟に皇帝位を譲ろうと思ったんだけど、まんまと断られて、結局<strong class=\"source-bold\">退位した</strong>。こうして、約300年続いた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロマノフ朝が滅亡</strong></span>したんだ（十月革命後、ニコライ2世とその家族は革命派によって処刑された）。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">臨時政府とソヴィエトの「二重権力」。そして、レーニンが帰国！</strong></span></h4>\n<p>革命によって、ロシアでは、<strong class=\"source-bold\">官僚と軍将校</strong>が支持する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">臨時政府</strong></span>と、<strong class=\"source-bold\">下層兵士</strong>が支持する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソヴィエト</strong></span>という2つの政治権力がある「<strong class=\"source-bold\">二重権力</strong>」状態が生まれたよ。<strong class=\"source-bold\">臨時政府</strong>の中心は<strong class=\"source-bold\">ブルジョワ政党</strong>である<strong class=\"source-bold\">立憲民主党</strong>ね。そこに<strong class=\"source-bold\">エスエル【社会革命党／社会主義者・革命家党】</strong>（右派）や<strong class=\"source-bold\">メンシェヴィキ</strong>の一部も参加していたんだけど、ブルジョワジーたちは「連合国の一員として戦争を続けよう」って主張したから、民衆が食糧難で苦しんでいるのに<strong class=\"source-bold\">戦争は終わらなかった</strong>。これに対して<strong class=\"source-bold\">ソヴィエト</strong>には、<strong class=\"source-bold\">エスエル</strong>（左派）や<strong class=\"source-bold\">メンシェヴィキ</strong>の指導のもとで、労働者や兵士、<strong class=\"source-bold\">農民</strong>が集まった。彼らは「戦争やめて食糧よこせ〜（パンと平和）」と、<strong class=\"source-bold\">停戦を求めていた</strong>んだ。</p>\n<blockquote><p>停戦を求めるソヴィエトと、戦争継続を主張する臨時政府。そりゃ、臨時政府は人気なくなるよ</p></blockquote>",
  "255": "<h2>255</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア革命</u></p>\n<p>こうした状況のロシアに、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ</strong></span>の指導者<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>が帰国したよ。<strong class=\"source-bold\">スイスに<ruby>亡命<rt>ぼうめい</rt></ruby>していたレーニン</strong>の帰国を助けたのはドイツ軍！。ドイツとしては、「革命が激化してロシアが戦争から脱落してくれればラッキー」とばかりに、途中乗り降りできない「<ruby>封印列車<rt>ふういんれっしゃ</rt></ruby>」にレーニンを乗せて国境まで送り届けたんだよ。途中でドイツ人に革命をふきこまれても困るしね。帰国したレーニンは、<strong class=\"source-bold\">ボリシェヴィキの方針</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">四月テーゼ</strong></span>を発表し、「<strong class=\"source-bold\">臨時政府を認めずに</strong>、労働者や農民を中心とする<strong class=\"source-bold\">ソヴィエトの多数派となって権力を握る</strong>」ことを主張した。さらに、<strong class=\"source-bold\">即時停戦</strong>を唱えて下層兵士への影響力を強めていったんだ。</p>\n<p>7月に入ると、ボリシェヴィキの影響を受けた下層兵士や労働者は、「<strong class=\"source-bold\">すべての権力をソヴィエトへ</strong>」をスローガンに<strong class=\"source-bold\">武装デモ</strong>を起こした（<strong class=\"source-bold\">七月<ruby>蜂起<rt>ほうき</rt></ruby></strong>）。しかし、<strong class=\"source-bold\">臨時政府によって鎮圧</strong>されてしまい、レーニンは再びフィンランドに逃亡した。しかし、労働者や農民の反発、そして<strong class=\"source-bold\">ウクライナ人などの自立</strong>の動きは強まっていったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">終わらない戦争と反革命……不満が爆発して十月革命が起こった！</strong></span></h4>\n<p>ソヴィエトの武装デモを鎮圧した臨時政府では、混乱を収拾するために<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span>／社会主義者・革命家党】</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケレンスキー</strong></span>を首相とする内閣をつくったよ。<strong class=\"source-bold\">エスエルは農民に影響力を持つ政党</strong>だから、これで人びとが落ち着くだろうと思っていた。しかし、政府のなかではケレンスキーとコルニーロフ将軍（帝政ロシア軍の司令官だった軍人）の対立が起こり、<strong class=\"source-bold\">コルニーロフが反革命軍</strong>（革命を<ruby>潰<rt>つぶ</rt></ruby>そうとする軍隊のことだ）<strong class=\"source-bold\">を首都に進撃させた</strong>んだ！。こうなると、反革命軍と戦う兵士はソヴィエトにしかいない……。<strong class=\"source-bold\">臨時政府はボリシェヴィキに協力を求め</strong>、このクーデタを鎮圧したんだ。</p>\n<p>反革命を倒し、しかも<strong class=\"source-bold\">停戦を主張するのがボリシェヴィキだけ</strong>だったから、<strong class=\"source-bold\">ソヴィエト内でのボリシェヴィキの人気が高まった</strong>！ 帰国した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レーニン</strong></span>や<strong class=\"source-bold\">トロツキー</strong>は「臨時政府を倒そう」って呼びかけ、1917年10月25日（西暦11月7日）、<strong class=\"source-bold\">ボリシェヴィキ派の労働者や兵士が蜂起</strong>して、<strong class=\"source-bold\">臨時政府を打倒</strong>した。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">十月革命</strong></span>（西暦では<strong class=\"source-bold\">十一月革命</strong>）だよ。<strong class=\"source-bold\">ケレンスキーはアメリカへ亡命</strong>したんだけど、見つからないように女装して逃げたっていわれてるよ。</p>\n<p>臨時政府が倒された翌日には、<strong class=\"source-bold\">全ロシア＝ソヴィエト会議</strong>（第2回）が開かれた。会議ではまず、当面の政府として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人民委員会議</strong></span>が設置され、<strong class=\"source-bold\">議長にレーニン、外務人民委員にトロツキー、民族人民委員にスターリン</strong>が選ばれた。さらに「<strong class=\"source-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong>」「<strong class=\"source-bold\">土地に関する布告</strong>」<strong class=\"source-bold\">が<ruby>採択<rt>さいたく</rt></ruby>された</strong>んだ。</p>\n<p>「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">平和に関する<ruby>布告<rt>ふこく</rt></ruby></strong></span>」は、第一次世界大戦に参戦しているすべての国に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無併合<rt>むへいごう</rt></ruby>・無償金</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>無賠償<rt>むばいしょう</rt></ruby></strong></span>】</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">・民族<ruby>自決<rt>じけつ</rt></ruby></strong></span>」の原則に基づいて、すぐに戦争終結のための講和交渉を始めるよう訴えたんだけど、<strong class=\"source-bold\">連合国側には完全に無視された</strong>んだ。これは一大事だよ。だって、ボリシェヴィキは即時停戦を主張して支持を集めていたから、戦争をやめなければ「約束が違う」と言われて、人気がガタ落ちにな</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "256": "<h2>256</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<p>る。連合国の対応に怒ったレーニンは「イギリスもフランスも、全員悪者じゃないか」として、<strong class=\"source-bold\">これまで連合国が結んだ秘密外交を暴露</strong>しまくったよ。もう一つの「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">土地に関する布告</strong></span>」は<strong class=\"source-bold\">土地私有権を廃止</strong>して地主から土地を没収するものだから、<strong class=\"source-bold\">社会主義政策の第一歩</strong>と考えられるね。</p>\n<blockquote><p>レーニンがサイクス・ピコ協定をバラしたから、イギリスの立場がヤバくなったんだよ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">選挙で負けたボリシェヴィキは……武力で議会を解散し、<ruby>独裁<rt>どくさい</rt></ruby>を確立！</strong></span></h4>\n<p>全ロシア＝ソヴィエト会議では、<strong class=\"source-bold\">ロシア初の普通選挙</strong>（女性にも参政権があるよ！）による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">憲法制定会議</strong></span>の招集を決めて、それまでの<ruby>暫定<rt>ざんてい</rt></ruby>的な政府として人民委員会議をつくった。ってことは、<strong class=\"source-bold\">選挙で勝たないと正式な政府にはなれない</strong>んだよ。<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ</strong></span>はかなり焦っていた。だって、<strong class=\"source-bold\">一番人口が多い農民</strong>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エスエル</strong></span><strong class=\"source-bold\">【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">社会革命党</strong></span>／社会主義者・革命家党】</strong>を支持しているからね。選挙で勝つには、すぐにでも<strong class=\"source-bold\">農民たちが求めている停戦を実現しないとマズい</strong>。だからトロツキーは、ドイツとの<ruby>講和<rt>こうわ</rt></ruby>を急いだんだ。</p>\n<p>ただ、<strong class=\"source-bold\">ドイツ</strong>はこれに気づいているから、「<strong class=\"source-bold\">ポーランド・ウクライナ・フィンランドなどをくれるなら、講和してやってもいい</strong>」とすごく強気だ。結局、選挙前の停戦は実現しなかったんだけど、のちにソヴィエト政権は<strong class=\"source-bold\">ドイツの要求を受け入れて</strong>、1918年3月に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブレスト＝リトフスク条約</strong></span>によって講和を実現した。レーニンは「ドイツでも社会主義革命をやれば、領土は取り返せる」って思ってたからね。こうしてロシア（ソヴィエト政権）は、第一次世界大戦から手を引いたんだ。レーニンをロシアに送り届けた<strong class=\"source-bold\">ドイツとしては、思惑どおりにロシアが脱落した</strong>、ってことになるのかな（とは言っても、ドイツも1918年のうちに敗戦するんだけど……）。</p>\n<p>さて、運命の<strong class=\"source-bold\">憲法制定会議選挙の結果</strong>はどうなった？っていうと……<strong class=\"source-bold\">ボリシェヴィキの完敗</strong>。<strong class=\"source-bold\">圧勝したのはエスエル</strong>だった。ボリシェヴィキは第2党だったけど、議席はエスエルの半分以下だもん。こうなると本当なら政権にはエスエルが就くはず……でも、そうはならなかったんだ。なんと、<strong class=\"source-bold\">選挙で負けたボリシェヴィキ</strong>は、1918年1月に開催された<strong class=\"source-bold\">議会を武力で閉鎖</strong>すると、そのまま解散させ、<strong class=\"source-bold\">一党独裁体制</strong>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボリシェヴィキ独裁</strong></span>）をつくった。そして3月には、ボリシェヴィキが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ロシア共産党</strong></span>と改称し、首都も<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モスクワ</strong></span>になった。ロシアはのちに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ソ連</strong></span>になるんだけど、史上初の社会主義革命は、武力クーデタで独裁体制をつくっただけ。しかも最初は「当分の間」と言ってた独裁が、実際は……ほぼソ連崩壊まで続くんだ。</p>",
  "257": "<h2>257</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ロシア革命</u></p>\n<p>それじゃ、これで第3章はおしまい。最後に年号 check しよう！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">‼</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h4>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">三国同盟の成立（独・墺・伊）</strong></td><td>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">882</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>派<rt>8</rt></ruby><ruby>閥<rt>82</rt></ruby></strong></span>をつくった　三国同盟）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">露仏同盟</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1891</strong></span>］</td><td>（露仏同盟　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>躍<rt>89</rt></ruby><ruby>1<rt>1</rt></ruby></strong></span>位）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">英仏協商の成立</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1904</strong></span>］</td><td>（ドイツに対抗　一緒に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>わ<rt>0</rt></ruby><ruby>よ<rt>4</rt></ruby></strong></span>）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">英露協商／三国協商の成立</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1907</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>は<rt>0</rt></ruby><ruby>仲<rt>7</rt></ruby></strong></span>良し　英仏ロシア）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">モロッコ事件（第1次／第2次）</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1905</strong></span>／19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">11</strong></span>］</td><td>（モロッコに　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>は<rt>0</rt></ruby><ruby>ゴ<rt>5</rt></ruby></strong></span>リ押し　<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>い<rt>1</rt></ruby></strong></span>感じ）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">第一次世界大戦<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1914</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>人<rt>1</rt></ruby><ruby>死<rt>4</rt></ruby></strong></span>ぬかも　大戦に）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ロシア革命</strong></td><td>［<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">1917</strong></span>］</td><td>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>得<rt>19</rt></ruby><ruby>意<rt>1</rt></ruby><ruby>な<rt>7</rt></ruby></strong></span>レーニン　革命起こす）</td></tr></tbody></table></div>\n<p>次回からは<strong class=\"source-bold\">第一次世界大戦後</strong>だよ。だんだんと現代の世界に近づいていくね。時代もひと区切りだから、ここまでであいまいなところは、もう一度確認しよう！</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "258": "<h2>258</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第13回</strong></span> 第一次世界大戦とロシア革命</p>\n<h3><span data-source-color=\"brown\" style=\"color:#a43725\"><strong class=\"source-bold\">近現代日本へのアプローチ</strong></span> <span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\">5</span></h3>\n<h4><strong class=\"source-bold\">〜日本の大衆政治運動〜</strong></h4>\n<p>19世紀半ば以降、<strong class=\"source-bold\">欧米各国で男性普通選挙が実現</strong>していたけど、20世紀初めの日本でも、<strong class=\"source-bold\">工業化</strong>が進んだことや<strong class=\"source-bold\">徴兵制</strong>を施行したことなどを背景に、大衆のデモや暴動が起きていたんだ！。例えば、旧<ruby>長州藩<rt>ちょうしゅうはん</rt></ruby>出身で軍人の<strong class=\"source-bold\"><ruby>桂太郎<rt>かつらたろう</rt></ruby>内閣</strong>（第3次）が衆議院で多数を占める立憲政友会と協力しなかったことから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次護憲運動</strong></span>が始まり、1913年にはなんと数万人の民衆が帝国議会を包囲して暴動も起きたから、<strong class=\"source-bold\">桂内閣は倒れた</strong>よ（<strong class=\"source-bold\">大正政変</strong>）。これって、日本で初めて<strong class=\"source-bold\">大衆運動によって内閣が倒れた</strong>ってことだね。こうした状況を受けて、1916年には政治学者の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>吉野作造<rt>よしのさくぞう</rt></ruby></strong></span>が、天皇主権のもとでもデモクラシーが可能であるとして、民衆のための政治をおこなう「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">民本主義</strong></span>」を唱えたんだ。また憲法学者の<strong class=\"source-bold\"><ruby>美濃部達吉<rt>みのべたつきち</rt></ruby></strong>は、主権は<strong class=\"source-bold\">国家にあって、天皇は国家の最高機関である</strong>と主張した（<strong class=\"source-bold\">天皇機関説</strong>）。</p>\n<p>さらに、1918年には、<strong class=\"source-bold\">シベリア出兵</strong>でコメが足りなくなるって噂から<strong class=\"source-bold\">コメの投機的な買い占め</strong>が起きて<strong class=\"source-bold\">米価が高騰</strong>すると、富山県から始まって全国でコメの値上げ<ruby>阻止<rt>そし</rt></ruby>を訴える暴動、いわゆる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">米騒動</strong></span>が起きた。政府は軍隊を出動させて<ruby>鎮圧<rt>ちんあつ</rt></ruby>したんだけど、騒動が収まると<strong class=\"source-bold\"><ruby>寺内正毅<rt>てらうちまさたけ</rt></ruby>内閣が責任をとって総辞職</strong>したんだ。さすがの元老たち（首相経験者などが、天皇の補佐という名目で首相選任権を持った）も<strong class=\"source-bold\">政党内閣</strong>を認め、立憲政友会の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>原敬<rt>はらたかし</rt></ruby></strong></span>が初めて<strong class=\"source-bold\">平民籍の衆議院議員から首相になった</strong>んだ（「<ruby>平民宰相<rt>へいみんさいしょう</rt></ruby>」）。</p>\n<p>こうして、大衆が<strong class=\"source-bold\">男性普通選挙を求めて</strong>たびたびデモなどを起こすようになり、1924年に再び貴族院を背景とする内閣ができると、衆議院の3政党（<strong class=\"source-bold\">憲政会・立憲政友会・革新倶楽部</strong>）が<strong class=\"source-bold\">護憲三派</strong>を結成して<strong class=\"source-bold\">第2次護憲運動</strong>を起こした。そして、解散後の衆議院選挙で圧勝すると、<strong class=\"source-bold\"><ruby>加藤高明<rt>かとうたかあき</rt></ruby>内閣（護憲三派内閣）</strong>ができて、1925年<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">男性普通選挙</strong></span>を実現したよ。でも、すでにコミンテルンの影響で<strong class=\"source-bold\">日本共産党</strong>が結成されて、<strong class=\"source-bold\">天皇制（「国体」）の廃止や私有財産の否定を主張</strong>していたから、これを取り締まるための<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">治安維持法</strong></span>も制定したよ。現在のような言論の自由とは程遠いね。</p>\n<p>ほかにも、<strong class=\"source-bold\">差別をなくそうとする社会運動</strong>が起きていたよ。1911年、<strong class=\"source-bold\"><ruby>平塚<rt>ひらつか</rt></ruby>らいてう</strong>（らいちょう）は<strong class=\"source-bold\"><ruby>青鞜社<rt>せいとうしゃ</rt></ruby></strong>を結成して女性運動を始めると、さらに女性参政権を求める運動へと発展させて、<strong class=\"source-bold\"><ruby>市川房江<rt>いちかわふさえ</rt></ruby></strong>らとともに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">新婦人協会</strong></span>をつくった。でも、<strong class=\"source-bold\">日本で女性参政権が認められるのは第二次世界大戦後</strong>だよ。</p>\n<p>また、根強く残っていた<strong class=\"source-bold\">被差別部落への社会的差別や偏見からの解放</strong>を自分たちの手で勝ち取ろうと<strong class=\"source-bold\">全国水平社</strong>が結成されて、部落解放運動が進められたんだ。ただ、こうした差別はいまだに解決したとはいえないね。</p>"
};

